"""HTTP API and static file server.

Deliberately a *local* web application rather than a desktop toolkit: the
browser gives a shop-floor-grade UI (large targets, drag and drop, zoomable
canvas, printable reports) with no build step and nothing to install beyond
pip. It binds to 127.0.0.1 and never reaches the network.

Endpoints are thin: validate, call ``app.vision``, serialise. All the
interesting behaviour lives in the vision layer, which is importable and
testable without starting a server.
"""

from __future__ import annotations

import time
from pathlib import Path
from typing import Any

import numpy as np
from fastapi import Body, FastAPI, File, HTTPException, Query, UploadFile
from fastapi.responses import FileResponse, HTMLResponse, JSONResponse, Response
from fastapi.staticfiles import StaticFiles
from pydantic import BaseModel, Field, field_validator

from app import storage
from app.config import (
    ALLOWED_UPLOAD_TYPES,
    APP_NAME,
    APP_VERSION,
    DEFAULT_SENSITIVITY,
    MAX_TEST_IMAGES_PER_RUN,
    MAX_UPLOAD_BYTES,
    SENSITIVITY_PRESETS,
    WEB_DIR,
    WORKING_LONG_EDGE,
)
from app.imaging import ImageError, decode_upload, fit_to_reference, to_working_size
from app.vision import crop_pair, inspect, suggest_parts

app = FastAPI(title=APP_NAME, version=APP_VERSION, docs_url="/api/docs", redoc_url=None)

NO_STORE = {"Cache-Control": "no-store, max-age=0"}


# --------------------------------------------------------------------------
# Request models
# --------------------------------------------------------------------------


class PartIn(BaseModel):
    id: str | None = None
    name: str = Field(default="", max_length=80)
    bbox: list[int] = Field(min_length=4, max_length=4)

    @field_validator("bbox")
    @classmethod
    def _positive_size(cls, value: list[int]) -> list[int]:
        if value[2] <= 0 or value[3] <= 0:
            raise ValueError("Box width and height must be positive.")
        return [int(v) for v in value]


class PartsPayload(BaseModel):
    parts: list[PartIn] = Field(default_factory=list, max_length=400)


class ProjectPatch(BaseModel):
    name: str | None = Field(default=None, max_length=120)
    sensitivity: str | None = None

    @field_validator("sensitivity")
    @classmethod
    def _known_preset(cls, value: str | None) -> str | None:
        if value is not None and value not in SENSITIVITY_PRESETS:
            raise ValueError("Unknown sensitivity preset.")
        return value


class ProjectCreate(BaseModel):
    name: str = Field(default="Untitled board", max_length=120)


# --------------------------------------------------------------------------
# Helpers
# --------------------------------------------------------------------------


def _bad_request(message: str) -> HTTPException:
    return HTTPException(status_code=400, detail=message)


def _require_project() -> storage.Project:
    project = storage.get_active()
    if project is None:
        raise HTTPException(status_code=404, detail="No active project.")
    return project


def _require_reference(project: storage.Project) -> np.ndarray:
    if project.reference is None or not project.reference_path.exists():
        raise _bad_request("Upload a reference board photo first.")
    return storage.load_reference(project)


def _read_upload(upload: UploadFile) -> np.ndarray:
    if upload.content_type and upload.content_type not in ALLOWED_UPLOAD_TYPES:
        raise _bad_request(
            f"'{upload.filename}' is a {upload.content_type} file. "
            "Upload a JPEG, PNG, BMP, WEBP or TIFF photo."
        )

    data = upload.file.read(MAX_UPLOAD_BYTES + 1)
    if len(data) > MAX_UPLOAD_BYTES:
        raise _bad_request(
            f"'{upload.filename}' is larger than {MAX_UPLOAD_BYTES // (1024 * 1024)} MB."
        )

    try:
        return decode_upload(data)
    except ImageError as exc:
        raise _bad_request(f"{upload.filename}: {exc}") from exc


def _project_payload(project: storage.Project) -> dict[str, Any]:
    payload = project.to_dict()
    payload["reference_url"] = (
        f"/api/project/reference.png?v={int(project.updated_at)}"
        if project.reference
        else None
    )
    payload["run_count"] = len(storage.list_runs(project))
    return payload


def _png(path: Path) -> FileResponse:
    if not path.exists():
        raise HTTPException(status_code=404, detail="Image not found.")
    return FileResponse(path, media_type="image/png", headers=NO_STORE)


# --------------------------------------------------------------------------
# Meta
# --------------------------------------------------------------------------


@app.get("/api/health")
def health() -> dict[str, Any]:
    return {"status": "ok", "app": APP_NAME, "version": APP_VERSION, "offline": True}


@app.get("/api/config")
def configuration() -> dict[str, Any]:
    return {
        "app": APP_NAME,
        "version": APP_VERSION,
        "working_long_edge": WORKING_LONG_EDGE,
        "max_test_images": MAX_TEST_IMAGES_PER_RUN,
        "max_upload_mb": MAX_UPLOAD_BYTES // (1024 * 1024),
        "default_sensitivity": DEFAULT_SENSITIVITY,
        "sensitivity_presets": [
            {
                "key": preset.key,
                "label": preset.label,
                "description": preset.description,
                "missing_threshold": preset.missing_threshold,
                "review_threshold": preset.review_threshold,
            }
            for preset in SENSITIVITY_PRESETS.values()
        ],
    }


# --------------------------------------------------------------------------
# Project
# --------------------------------------------------------------------------


@app.get("/api/project")
def get_project() -> dict[str, Any]:
    return _project_payload(storage.get_or_create_active())


@app.post("/api/project")
def create_project(payload: ProjectCreate = Body(default=ProjectCreate())) -> dict[str, Any]:
    return _project_payload(storage.create_project(payload.name))


@app.patch("/api/project")
def patch_project(payload: ProjectPatch) -> dict[str, Any]:
    project = _require_project()
    if payload.name is not None:
        project.name = payload.name.strip() or project.name
    if payload.sensitivity is not None:
        project.sensitivity = payload.sensitivity
    storage.save_project(project)
    return _project_payload(project)


@app.post("/api/project/reference")
def upload_reference(file: UploadFile = File(...)) -> dict[str, Any]:
    project = storage.get_or_create_active()
    image = to_working_size(_read_upload(file))
    storage.store_reference(project, image, original_filename=file.filename or "")
    return _project_payload(project)


@app.get("/api/project/reference.png")
def reference_image() -> FileResponse:
    project = _require_project()
    return _png(project.reference_path)


@app.put("/api/project/parts")
def save_parts(payload: PartsPayload) -> dict[str, Any]:
    project = _require_project()
    if project.reference is None:
        raise _bad_request("Upload a reference board photo first.")

    width, height = project.reference.width, project.reference.height
    parts: list[storage.Part] = []

    for index, incoming in enumerate(payload.parts, start=1):
        x, y, w, h = incoming.bbox
        x = max(0, min(x, width - 1))
        y = max(0, min(y, height - 1))
        w = max(4, min(w, width - x))
        h = max(4, min(h, height - y))

        name = incoming.name.strip() or f"Part {index}"
        parts.append(
            storage.Part(
                id=incoming.id or storage.Part.new(name, [x, y, w, h]).id,
                name=name,
                bbox=[x, y, w, h],
            )
        )

    project.parts = parts
    storage.save_project(project)
    return _project_payload(project)


@app.post("/api/project/suggest")
def suggest() -> dict[str, Any]:
    project = _require_project()
    reference = _require_reference(project)
    started = time.perf_counter()
    suggestions = suggest_parts(reference)
    return {
        "suggestions": suggestions,
        "count": len(suggestions),
        "elapsed_ms": round((time.perf_counter() - started) * 1000, 1),
    }


@app.get("/api/project/export")
def export_project() -> JSONResponse:
    project = _require_project()
    payload = storage.export_project(project)
    safe_name = "".join(c for c in project.name if c.isalnum() or c in " -_").strip()
    filename = f"{safe_name or 'board'}.pcbproj.json"
    return JSONResponse(
        payload,
        headers={
            "Content-Disposition": f'attachment; filename="{filename}"',
            **NO_STORE,
        },
    )


@app.post("/api/project/import")
def import_project(file: UploadFile = File(...)) -> dict[str, Any]:
    import json

    raw = file.file.read(MAX_UPLOAD_BYTES + 1)
    if len(raw) > MAX_UPLOAD_BYTES:
        raise _bad_request("That project file is too large.")
    try:
        payload = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise _bad_request("That file is not a readable project export.") from exc

    try:
        project = storage.import_project(payload)
    except ValueError as exc:
        raise _bad_request(str(exc)) from exc
    return _project_payload(project)


# --------------------------------------------------------------------------
# Projects list
# --------------------------------------------------------------------------


@app.get("/api/projects")
def projects() -> dict[str, Any]:
    return {"projects": storage.list_projects(), "active_id": storage.get_active_id()}


@app.post("/api/projects/{project_id}/activate")
def activate_project(project_id: str) -> dict[str, Any]:
    project = storage.load_project(project_id)
    if project is None:
        raise HTTPException(status_code=404, detail="Project not found.")
    storage.set_active(project_id)
    return _project_payload(project)


@app.delete("/api/projects/{project_id}")
def remove_project(project_id: str) -> dict[str, Any]:
    if not storage.delete_project(project_id):
        raise HTTPException(status_code=404, detail="Project not found.")
    return {"deleted": project_id}


# --------------------------------------------------------------------------
# Inspection
# --------------------------------------------------------------------------


@app.post("/api/inspect")
def run_inspection(
    files: list[UploadFile] = File(...),
    sensitivity: str | None = Query(default=None),
) -> dict[str, Any]:
    project = _require_project()
    reference = _require_reference(project)

    if not project.parts:
        raise _bad_request(
            "Name at least one part on the reference board before inspecting."
        )
    if len(files) > MAX_TEST_IMAGES_PER_RUN:
        raise _bad_request(
            f"Upload at most {MAX_TEST_IMAGES_PER_RUN} photos at a time."
        )

    preset = sensitivity or project.sensitivity or DEFAULT_SENSITIVITY
    if preset not in SENSITIVITY_PRESETS:
        preset = DEFAULT_SENSITIVITY

    parts = [{"id": p.id, "name": p.name, "bbox": p.bbox} for p in project.parts]
    results: list[dict[str, Any]] = []

    for upload in files:
        started = time.perf_counter()
        image = fit_to_reference(to_working_size(_read_upload(upload)), reference.shape)

        result = inspect(reference, parts, image, sensitivity=preset)
        elapsed_ms = round((time.perf_counter() - started) * 1000, 1)

        run_id = storage.new_run_id()
        aligned = result.aligned_image if result.aligned_image is not None else image

        crops = {
            verdict.part_id: crop_pair(reference, aligned, verdict)
            for verdict in result.verdicts
        }

        payload: dict[str, Any] = {
            "run_id": run_id,
            "project_id": project.id,
            "filename": upload.filename or "photo",
            "created_at": time.time(),
            "elapsed_ms": elapsed_ms,
            "sensitivity": result.sensitivity,
            "thresholds": result.thresholds,
            "summary": result.summary(),
            "alignment": result.alignment.to_dict(),
            "photometric": result.photometric,
            "scene_compensation": result.scene_compensation,
            "warnings": result.warnings,
            "verdicts": [v.to_dict() for v in result.verdicts],
            "images": {
                "test": f"/api/runs/{run_id}/image/test.png",
                "aligned": f"/api/runs/{run_id}/image/aligned.png",
                "reference": f"/api/project/reference.png?v={int(project.updated_at)}",
            },
            "size": {"width": int(reference.shape[1]), "height": int(reference.shape[0])},
        }

        storage.store_run(project, run_id, payload, image, aligned, crops)
        results.append(payload)

    if sensitivity and sensitivity != project.sensitivity:
        project.sensitivity = preset
        storage.save_project(project)

    total_missing = sum(r["summary"]["missing_count"] for r in results)
    return {
        "results": results,
        "batch": {
            "count": len(results),
            "ok_count": sum(1 for r in results if r["summary"]["status"] == "present"),
            "missing_boards": sum(1 for r in results if r["summary"]["missing_count"] > 0),
            "total_missing_parts": total_missing,
        },
    }


@app.get("/api/runs")
def list_runs() -> dict[str, Any]:
    project = _require_project()
    return {"runs": storage.list_runs(project)}


@app.get("/api/runs/{run_id}")
def get_run(run_id: str) -> dict[str, Any]:
    project = _require_project()
    payload = storage.load_run(project, run_id)
    if payload is None:
        raise HTTPException(status_code=404, detail="Inspection run not found.")
    return payload


@app.delete("/api/runs")
def clear_runs() -> dict[str, Any]:
    project = _require_project()
    storage.clear_runs(project)
    return {"cleared": True}


@app.get("/api/runs/{run_id}/image/{name}")
def run_image(run_id: str, name: str) -> FileResponse:
    if name not in {"test.png", "aligned.png"}:
        raise HTTPException(status_code=404, detail="Unknown image.")
    project = _require_project()
    return _png(storage.run_directory(project, run_id) / name)


@app.get("/api/runs/{run_id}/crop/{part_id}/{which}.png")
def run_crop(run_id: str, part_id: str, which: str) -> FileResponse:
    if which not in {"reference", "test"}:
        raise HTTPException(status_code=404, detail="Unknown crop.")
    if not part_id.isalnum():
        raise HTTPException(status_code=400, detail="Invalid part id.")
    project = _require_project()
    path = storage.run_directory(project, run_id) / "crops" / f"{part_id}-{which}.png"
    return _png(path)


# --------------------------------------------------------------------------
# Static front-end
# --------------------------------------------------------------------------


@app.get("/", response_class=HTMLResponse)
def index() -> Response:
    html = (WEB_DIR / "index.html").read_text(encoding="utf-8")
    return HTMLResponse(html, headers=NO_STORE)


@app.get("/favicon.svg")
def favicon() -> FileResponse:
    return FileResponse(WEB_DIR / "assets" / "favicon.svg", media_type="image/svg+xml")


app.mount("/static", StaticFiles(directory=str(WEB_DIR)), name="static")

