/* ==========================================================================
   PCB Inspector — interface styles

   Self-contained by requirement: no CDN, no web-font request, no external
   asset of any kind, because the application must run with the network
   unplugged. Typography therefore uses the platform UI stack, which also
   renders instantly and matches whatever machine is on the factory desk.

   Visual intent: a precision instrument. Dark by default (a line workstation
   usually is), calm surfaces, one accent colour, and status colour reserved
   exclusively for verdicts so that red always means exactly one thing.
   ========================================================================== */

/* --------------------------------------------------------------------------
   1. Tokens
   -------------------------------------------------------------------------- */

:root {
  --brand:        #6e8bff;
  --brand-alt:    #a78bfa;
  --brand-soft:   rgba(110, 139, 255, 0.14);
  --brand-line:   rgba(110, 139, 255, 0.42);

  --ok:           #2bd47d;
  --ok-soft:      rgba(43, 212, 125, 0.13);
  --review:       #f5a524;
  --review-soft:  rgba(245, 165, 36, 0.14);
  --missing:      #fb5d6d;
  --missing-soft: rgba(251, 93, 109, 0.14);

  --radius-sm: 8px;
  --radius:    13px;
  --radius-lg: 20px;

  --ease: cubic-bezier(0.22, 0.61, 0.36, 1);
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);

  --font: -apple-system, BlinkMacSystemFont, "Segoe UI Variable Text", "Segoe UI",
          Roboto, "Helvetica Neue", Arial, sans-serif;
  --mono: "SF Mono", "Cascadia Mono", "Segoe UI Mono", "Roboto Mono",
          ui-monospace, Menlo, Consolas, monospace;

  --appbar-h: 68px;
}

:root[data-theme="dark"] {
  --bg:          #070a10;
  --surface-1:   #0d121b;
  --surface-2:   #121a26;
  --surface-3:   #18222f;
  --surface-up:  #1d2838;
  --border:      #1f2b3c;
  --border-soft: #192332;
  --border-str:  #2d3f58;

  --text:        #e9eff8;
  --text-mid:    #9fb0c6;
  --text-dim:    #6b7c93;

  --shadow-1: 0 1px 2px rgba(0, 0, 0, 0.5);
  --shadow-2: 0 8px 24px -8px rgba(0, 0, 0, 0.7);
  --shadow-3: 0 28px 70px -24px rgba(0, 0, 0, 0.85);
  --glass: rgba(13, 18, 27, 0.72);
  --aurora-opacity: 0.5;
  --canvas-bg: #070a10;
}

:root[data-theme="light"] {
  --bg:          #f2f5fa;
  --surface-1:   #ffffff;
  --surface-2:   #f7f9fc;
  --surface-3:   #eef2f8;
  --surface-up:  #ffffff;
  --border:      #dde4ee;
  --border-soft: #e8edf4;
  --border-str:  #c3cedd;

  --text:        #0d1522;
  --text-mid:    #4e6076;
  --text-dim:    #74859a;

  --brand-soft:  rgba(110, 139, 255, 0.11);
  --ok:          #12a85e;
  --review:      #c77700;
  --missing:     #e0384f;

  --shadow-1: 0 1px 2px rgba(16, 32, 56, 0.07);
  --shadow-2: 0 10px 26px -12px rgba(16, 32, 56, 0.22);
  --shadow-3: 0 30px 70px -28px rgba(16, 32, 56, 0.3);
  --glass: rgba(255, 255, 255, 0.78);
  --aurora-opacity: 0.32;
  --canvas-bg: #e9eef5;
}

/* --------------------------------------------------------------------------
   2. Base
   -------------------------------------------------------------------------- */

*, *::before, *::after { box-sizing: border-box; }

html, body { height: 100%; }

body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: var(--font);
  font-size: 15px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overflow-x: hidden;
}

h1, h2, h3, h4 { margin: 0; font-weight: 640; letter-spacing: -0.021em; line-height: 1.25; }
h2 { font-size: 1.32rem; }
h3 { font-size: 1.02rem; }
p  { margin: 0; }

button, input, select, textarea { font: inherit; color: inherit; }
button { cursor: pointer; }

kbd {
  font-family: var(--mono);
  font-size: 0.74em;
  padding: 2px 6px;
  border-radius: 5px;
  border: 1px solid var(--border-str);
  background: var(--surface-3);
  box-shadow: inset 0 -1.5px 0 rgba(0, 0, 0, 0.18);
  white-space: nowrap;
}

u { text-decoration-color: var(--brand-line); text-underline-offset: 3px; }

.is-hidden { display: none !important; }

:focus-visible {
  outline: 2px solid var(--brand);
  outline-offset: 2px;
  border-radius: 4px;
}

::selection { background: var(--brand-soft); }

/* Scrollbars — thin, unobtrusive, themed. */
* { scrollbar-width: thin; scrollbar-color: var(--border-str) transparent; }
*::-webkit-scrollbar { width: 10px; height: 10px; }
*::-webkit-scrollbar-thumb {
  background: var(--border-str);
  border-radius: 99px;
  border: 3px solid transparent;
  background-clip: content-box;
}
*::-webkit-scrollbar-track { background: transparent; }

/* --------------------------------------------------------------------------
   3. Ambient background
   -------------------------------------------------------------------------- */

.aurora {
  position: fixed;
  inset: 0;
  z-index: 0;
  overflow: hidden;
  pointer-events: none;
  opacity: var(--aurora-opacity);
}

.aurora__blob {
  position: absolute;
  border-radius: 50%;
  filter: blur(110px);
  will-change: transform;
}

.aurora__blob--a {
  width: 46vw; height: 46vw;
  top: -16vw; left: -8vw;
  background: radial-gradient(circle, var(--brand) 0%, transparent 68%);
  animation: drift-a 34s var(--ease) infinite alternate;
}
.aurora__blob--b {
  width: 38vw; height: 38vw;
  top: 14vh; right: -10vw;
  background: radial-gradient(circle, var(--brand-alt) 0%, transparent 68%);
  animation: drift-b 41s var(--ease) infinite alternate;
}
.aurora__blob--c {
  width: 34vw; height: 34vw;
  bottom: -14vw; left: 32vw;
  background: radial-gradient(circle, #2bd4c0 0%, transparent 70%);
  animation: drift-c 47s var(--ease) infinite alternate;
}

@keyframes drift-a { to { transform: translate3d(7vw, 6vh, 0) scale(1.14); } }
@keyframes drift-b { to { transform: translate3d(-6vw, 9vh, 0) scale(0.88); } }
@keyframes drift-c { to { transform: translate3d(5vw, -7vh, 0) scale(1.1); } }

@media (prefers-reduced-motion: reduce) {
  .aurora__blob { animation: none; }
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    transition-duration: 0.001ms !important;
  }
}

/* --------------------------------------------------------------------------
   4. App bar
   -------------------------------------------------------------------------- */

.appbar {
  position: sticky;
  top: 0;
  z-index: 40;
  height: var(--appbar-h);
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 0 22px;
  background: var(--glass);
  backdrop-filter: blur(22px) saturate(180%);
  -webkit-backdrop-filter: blur(22px) saturate(180%);
  border-bottom: 1px solid var(--border);
}

.appbar__brand { display: flex; align-items: center; gap: 11px; min-width: 0; }

.mark { width: 34px; height: 34px; flex: none; }
.mark__trace {
  stroke-dasharray: 46;
  stroke-dashoffset: 46;
  animation: trace 1.5s var(--ease-out) 0.15s forwards;
}
.mark__node { opacity: 0; animation: pop 0.5s var(--ease-out) 1.1s forwards; }
@keyframes trace { to { stroke-dashoffset: 0; } }
@keyframes pop { to { opacity: 1; } }

.appbar__titles { min-width: 0; }
.appbar__titles h1 {
  font-size: 0.95rem;
  letter-spacing: -0.01em;
  line-height: 1.15;
}
.appbar__project {
  display: block;
  max-width: 220px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  padding: 0;
  border: 0;
  background: none;
  color: var(--text-dim);
  font-size: 0.78rem;
  text-align: left;
  border-bottom: 1px dashed transparent;
  transition: color 0.16s var(--ease), border-color 0.16s var(--ease);
}
.appbar__project:hover { color: var(--text-mid); border-bottom-color: var(--border-str); }

.appbar__actions { margin-left: auto; display: flex; align-items: center; gap: 10px; }

/* --------------------------------------------------------------------------
   5. Stepper
   -------------------------------------------------------------------------- */

.stepper {
  display: flex;
  align-items: center;
  gap: 4px;
  margin: 0 auto;
}

.stepper__item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 7px 13px 7px 8px;
  border: 1px solid transparent;
  border-radius: 99px;
  background: none;
  color: var(--text-dim);
  transition: color 0.18s var(--ease), background 0.18s var(--ease),
              border-color 0.18s var(--ease);
}
.stepper__item:hover:not(:disabled) { color: var(--text-mid); background: var(--surface-2); }
.stepper__item:disabled { opacity: 0.4; cursor: not-allowed; }

.stepper__num {
  display: grid;
  place-items: center;
  width: 25px; height: 25px;
  flex: none;
  border-radius: 50%;
  border: 1.5px solid currentColor;
  font-size: 0.76rem;
  font-weight: 650;
  font-variant-numeric: tabular-nums;
  transition: background 0.18s var(--ease), color 0.18s var(--ease),
              border-color 0.18s var(--ease);
}

.stepper__text { display: flex; flex-direction: column; text-align: left; }
.stepper__text b { font-size: 0.82rem; font-weight: 620; letter-spacing: -0.01em; }
.stepper__text i {
  font-style: normal;
  font-size: 0.7rem;
  color: var(--text-dim);
  line-height: 1.2;
}

.stepper__item.is-active {
  color: var(--text);
  background: var(--brand-soft);
  border-color: var(--brand-line);
}
.stepper__item.is-active .stepper__num {
  background: var(--brand);
  border-color: var(--brand);
  color: #fff;
}
.stepper__item.is-done .stepper__num { background: var(--ok-soft); border-color: var(--ok); color: var(--ok); }

.stepper__rule { width: 22px; height: 1px; background: var(--border); flex: none; }

@media (max-width: 1180px) {
  .stepper__text i { display: none; }
}
@media (max-width: 960px) {
  .stepper { order: 3; width: 100%; }
  .appbar { height: auto; flex-wrap: wrap; padding: 12px 16px; gap: 12px; }
}

/* --------------------------------------------------------------------------
   6. Controls
   -------------------------------------------------------------------------- */

.btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 9px 17px;
  border-radius: 10px;
  border: 1px solid var(--border-str);
  background: var(--surface-2);
  color: var(--text);
  font-size: 0.875rem;
  font-weight: 560;
  letter-spacing: -0.005em;
  white-space: nowrap;
  transition: transform 0.14s var(--ease), background 0.16s var(--ease),
              border-color 0.16s var(--ease), box-shadow 0.16s var(--ease),
              opacity 0.16s var(--ease);
}
.btn:hover:not(:disabled) { background: var(--surface-3); border-color: var(--border-str); }
.btn:active:not(:disabled) { transform: translateY(1px); }
.btn:disabled { opacity: 0.42; cursor: not-allowed; }

.btn--primary {
  background: linear-gradient(135deg, var(--brand), var(--brand-alt));
  border-color: transparent;
  color: #fff;
  box-shadow: 0 6px 18px -8px var(--brand), var(--shadow-1);
}
.btn--primary:hover:not(:disabled) {
  filter: brightness(1.07);
  box-shadow: 0 10px 26px -10px var(--brand), var(--shadow-1);
}

.btn--ghost { background: transparent; }
.btn--ghost:hover:not(:disabled) { background: var(--surface-2); }

.btn--sm { padding: 6px 12px; font-size: 0.8rem; border-radius: 8px; }
.btn__icon { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.7; }

.icon-btn {
  display: grid;
  place-items: center;
  width: 36px; height: 36px;
  border-radius: 10px;
  border: 1px solid transparent;
  background: transparent;
  color: var(--text-mid);
  transition: background 0.16s var(--ease), color 0.16s var(--ease);
}
.icon-btn:hover { background: var(--surface-2); color: var(--text); }
.icon-btn svg {
  width: 19px; height: 19px;
  fill: none; stroke: currentColor;
  stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round;
}
.icon-btn--sm { width: 30px; height: 30px; }
.icon-btn--sm svg { width: 16px; height: 16px; }

:root[data-theme="dark"] .icon-sun { display: block; }
:root[data-theme="dark"] .icon-moon { display: none; }
:root[data-theme="light"] .icon-sun { display: none; }
:root[data-theme="light"] .icon-moon { display: block; }

.select {
  appearance: none;
  padding: 7px 30px 7px 11px;
  border-radius: 9px;
  border: 1px solid var(--border-str);
  background: var(--surface-2);
  font-size: 0.82rem;
  font-weight: 540;
  background-image: linear-gradient(45deg, transparent 50%, currentColor 50%),
                    linear-gradient(135deg, currentColor 50%, transparent 50%);
  background-position: calc(100% - 15px) 53%, calc(100% - 10px) 53%;
  background-size: 5px 5px, 5px 5px;
  background-repeat: no-repeat;
}

.field--inline { display: flex; align-items: center; gap: 8px; }
.field__label { font-size: 0.74rem; color: var(--text-dim); text-transform: uppercase; letter-spacing: 0.07em; }
@media (max-width: 1080px) { .field__label { display: none; } }

.row { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
.row--end { justify-content: flex-end; }

.segmented {
  display: inline-flex;
  padding: 3px;
  gap: 2px;
  border-radius: 10px;
  border: 1px solid var(--border);
  background: var(--surface-2);
}
.segmented button {
  padding: 5px 13px;
  border: 0;
  border-radius: 7px;
  background: none;
  color: var(--text-dim);
  font-size: 0.8rem;
  font-weight: 560;
  transition: background 0.16s var(--ease), color 0.16s var(--ease);
}
.segmented button.is-active { background: var(--surface-up); color: var(--text); box-shadow: var(--shadow-1); }

.menu { position: relative; }
.menu__panel {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  min-width: 224px;
  padding: 6px;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  background: var(--surface-up);
  box-shadow: var(--shadow-3);
  opacity: 0;
  transform: translateY(-6px) scale(0.98);
  pointer-events: none;
  transition: opacity 0.16s var(--ease), transform 0.16s var(--ease);
  z-index: 50;
}
.menu.is-open .menu__panel { opacity: 1; transform: none; pointer-events: auto; }
.menu__panel button {
  display: block;
  width: 100%;
  padding: 8px 11px;
  border: 0;
  border-radius: 8px;
  background: none;
  text-align: left;
  font-size: 0.855rem;
  color: var(--text-mid);
}
.menu__panel button:hover { background: var(--surface-2); color: var(--text); }
.menu__sep { height: 1px; margin: 5px 8px; background: var(--border-soft); }

/* --------------------------------------------------------------------------
   7. Layout & panels
   -------------------------------------------------------------------------- */

#main {
  position: relative;
  z-index: 1;
  max-width: 1460px;
  margin: 0 auto;
  padding: 30px 22px 72px;
}

.panel { animation: panel-in 0.4s var(--ease-out); }
@keyframes panel-in {
  from { opacity: 0; transform: translateY(10px); }
  to   { opacity: 1; transform: none; }
}

.panel__head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
  margin-bottom: 24px;
}
.panel__head p {
  margin-top: 6px;
  max-width: 62ch;
  color: var(--text-mid);
  font-size: 0.92rem;
}

.card {
  padding: 20px;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  background: var(--surface-1);
  box-shadow: var(--shadow-2);
}

.note { color: var(--text-dim); font-size: 0.8rem; line-height: 1.5; }

/* --------------------------------------------------------------------------
   8. Dropzone
   -------------------------------------------------------------------------- */

.dropzone {
  display: grid;
  place-items: center;
  gap: 7px;
  min-height: 320px;
  padding: 40px;
  border-radius: var(--radius-lg);
  border: 1.5px dashed var(--border-str);
  background: var(--surface-1);
  text-align: center;
  transition: border-color 0.2s var(--ease), background 0.2s var(--ease),
              transform 0.2s var(--ease);
}
.dropzone:hover, .dropzone:focus-visible { border-color: var(--brand-line); background: var(--surface-2); }
.dropzone.is-over {
  border-color: var(--brand);
  background: var(--brand-soft);
  transform: scale(1.006);
}
.dropzone--compact { min-height: 180px; padding: 28px; }

.dropzone__icon {
  width: 46px; height: 46px;
  fill: none; stroke: var(--text-dim);
  stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round;
  transition: stroke 0.2s var(--ease), transform 0.3s var(--ease-out);
}
.dropzone:hover .dropzone__icon, .dropzone.is-over .dropzone__icon {
  stroke: var(--brand);
  transform: translateY(-3px);
}
.dropzone__title { font-weight: 600; font-size: 1.02rem; }
.dropzone__hint { color: var(--text-dim); font-size: 0.83rem; }

.reference-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 330px;
  gap: 20px;
}
@media (max-width: 900px) { .reference-layout { grid-template-columns: 1fr; } }

.card--guide h3 { margin-bottom: 12px; }
.guide-list { margin: 0 0 14px; padding-left: 18px; color: var(--text-mid); font-size: 0.875rem; }
.guide-list li { margin-bottom: 7px; }
.guide-list b { color: var(--text); font-weight: 600; }

/* --------------------------------------------------------------------------
   9. Reference preview
   -------------------------------------------------------------------------- */

.reference-preview {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px;
  gap: 24px;
  align-items: start;
}
@media (max-width: 900px) { .reference-preview { grid-template-columns: 1fr; } }

.preview-frame {
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  background: var(--canvas-bg);
  overflow: hidden;
  box-shadow: var(--shadow-3);
}
.preview-frame img { display: block; width: 100%; height: auto; }

.preview-meta h3 { margin-bottom: 14px; }

.meta-list { margin: 0 0 20px; display: grid; gap: 10px; }
.meta-list > div {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding-bottom: 9px;
  border-bottom: 1px solid var(--border-soft);
}
.meta-list dt { color: var(--text-dim); font-size: 0.82rem; }
.meta-list dd {
  margin: 0;
  font-size: 0.82rem;
  font-weight: 560;
  font-variant-numeric: tabular-nums;
  text-align: right;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 190px;
}

/* --------------------------------------------------------------------------
   10. Annotation editor
   -------------------------------------------------------------------------- */

.editor {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 316px;
  gap: 18px;
  align-items: start;
}
@media (max-width: 1000px) { .editor { grid-template-columns: 1fr; } }

.editor__stage {
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  background: var(--surface-1);
  overflow: hidden;
  box-shadow: var(--shadow-2);
}

.stage-toolbar {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 9px 12px;
  border-bottom: 1px solid var(--border);
  background: var(--surface-2);
}
.toolgroup { display: flex; align-items: center; gap: 4px; }
.stage-hint {
  margin: 0 auto;
  color: var(--text-dim);
  font-size: 0.78rem;
  text-align: center;
}
@media (max-width: 820px) { .stage-hint { display: none; } }

.zoom-readout {
  min-width: 48px;
  text-align: center;
  font-size: 0.76rem;
  font-variant-numeric: tabular-nums;
  color: var(--text-mid);
}

.canvas-host {
  position: relative;
  height: min(66vh, 680px);
  background:
    linear-gradient(var(--border-soft) 1px, transparent 1px) 0 0 / 28px 28px,
    linear-gradient(90deg, var(--border-soft) 1px, transparent 1px) 0 0 / 28px 28px,
    var(--canvas-bg);
  overflow: hidden;
  touch-action: none;
}
.canvas-host canvas { display: block; width: 100%; height: 100%; cursor: crosshair; }
.canvas-host.is-panning canvas { cursor: grabbing; }
.canvas-host.is-pannable canvas { cursor: grab; }

.canvas-empty {
  position: absolute;
  left: 50%; bottom: 20px;
  transform: translateX(-50%);
  padding: 9px 18px;
  border-radius: 99px;
  border: 1px solid var(--border);
  background: var(--glass);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  color: var(--text-mid);
  font-size: 0.82rem;
  pointer-events: none;
}

.editor__side {
  display: flex;
  flex-direction: column;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  background: var(--surface-1);
  box-shadow: var(--shadow-2);
  max-height: min(calc(66vh + 48px), 728px);
  overflow: hidden;
}
.side-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 13px 15px;
  border-bottom: 1px solid var(--border);
}
.count-pill {
  display: inline-grid;
  place-items: center;
  min-width: 23px;
  height: 21px;
  padding: 0 7px;
  margin-left: 6px;
  border-radius: 99px;
  background: var(--brand-soft);
  color: var(--brand);
  font-size: 0.74rem;
  font-weight: 650;
  font-variant-numeric: tabular-nums;
}

.part-list { margin: 0; padding: 7px; list-style: none; overflow-y: auto; flex: 1; }

.part-row {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 7px 9px;
  border-radius: 9px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: background 0.14s var(--ease), border-color 0.14s var(--ease);
}
.part-row:hover { background: var(--surface-2); }
.part-row.is-selected { background: var(--brand-soft); border-color: var(--brand-line); }

.part-row__index {
  width: 22px;
  flex: none;
  color: var(--text-dim);
  font-size: 0.72rem;
  font-variant-numeric: tabular-nums;
  text-align: right;
}
.part-row__name {
  flex: 1;
  min-width: 0;
  padding: 3px 6px;
  border: 1px solid transparent;
  border-radius: 6px;
  background: transparent;
  font-size: 0.855rem;
  font-weight: 550;
  overflow: hidden;
  text-overflow: ellipsis;
}
.part-row__name:hover { border-color: var(--border); }
.part-row__name:focus { border-color: var(--brand); background: var(--bg); outline: none; }
.part-row__dims {
  color: var(--text-dim);
  font-size: 0.7rem;
  font-family: var(--mono);
  flex: none;
}
.part-row__del {
  width: 24px; height: 24px;
  flex: none;
  display: grid;
  place-items: center;
  border: 0;
  border-radius: 6px;
  background: none;
  color: var(--text-dim);
  opacity: 0;
  transition: opacity 0.14s var(--ease), color 0.14s var(--ease), background 0.14s var(--ease);
}
.part-row:hover .part-row__del, .part-row__del:focus-visible { opacity: 1; }
.part-row__del:hover { background: var(--missing-soft); color: var(--missing); }
.part-row__del svg { width: 14px; height: 14px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }

.side-empty { padding: 26px 20px; text-align: center; color: var(--text-mid); }
.side-empty p + p { margin-top: 8px; }

/* --------------------------------------------------------------------------
   11. Inspection results
   -------------------------------------------------------------------------- */

.progress { margin: 22px 0; }
.progress__bar {
  height: 4px;
  border-radius: 99px;
  background: var(--surface-3);
  overflow: hidden;
}
.progress__bar span {
  display: block;
  height: 100%;
  width: 0;
  border-radius: 99px;
  background: linear-gradient(90deg, var(--brand), var(--brand-alt));
  transition: width 0.35s var(--ease);
}
.progress p { margin-top: 9px; color: var(--text-mid); font-size: 0.84rem; }

.batch-summary {
  display: flex;
  align-items: center;
  gap: 26px;
  flex-wrap: wrap;
  margin: 24px 0 18px;
  padding: 16px 22px;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  background: var(--surface-1);
  box-shadow: var(--shadow-1);
}
.stat { display: flex; flex-direction: column; gap: 1px; }
.stat__value { font-size: 1.5rem; font-weight: 660; font-variant-numeric: tabular-nums; letter-spacing: -0.025em; }
.stat__label { font-size: 0.73rem; color: var(--text-dim); text-transform: uppercase; letter-spacing: 0.07em; }
.stat--ok .stat__value { color: var(--ok); }
.stat--missing .stat__value { color: var(--missing); }
.stat__sep { width: 1px; align-self: stretch; background: var(--border); }

.results {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(330px, 1fr));
  gap: 18px;
  margin-top: 20px;
}

.board-card {
  display: flex;
  flex-direction: column;
  border-radius: var(--radius-lg);
  border: 1px solid var(--border);
  background: var(--surface-1);
  overflow: hidden;
  cursor: pointer;
  box-shadow: var(--shadow-2);
  transition: transform 0.26s var(--ease-out), box-shadow 0.26s var(--ease-out),
              border-color 0.2s var(--ease);
  animation: card-in 0.45s var(--ease-out) both;
}
@keyframes card-in {
  from { opacity: 0; transform: translateY(14px) scale(0.985); }
  to   { opacity: 1; transform: none; }
}
.board-card:hover {
  transform: translateY(-3px);
  box-shadow: var(--shadow-3);
  border-color: var(--border-str);
}

.board-card__media {
  position: relative;
  aspect-ratio: 3 / 2;
  background: var(--canvas-bg);
  overflow: hidden;
}
.board-card__media canvas { display: block; width: 100%; height: 100%; object-fit: contain; }

.board-card__banner {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 11px 15px;
  font-weight: 640;
  font-size: 0.92rem;
  letter-spacing: -0.01em;
}
.board-card__banner svg { width: 18px; height: 18px; flex: none; fill: none; stroke: currentColor; stroke-width: 2.1; stroke-linecap: round; stroke-linejoin: round; }
.banner--ok      { background: var(--ok-soft);      color: var(--ok); }
.banner--review  { background: var(--review-soft);  color: var(--review); }
.banner--missing { background: var(--missing-soft); color: var(--missing); }

.board-card__body { padding: 13px 15px 15px; display: flex; flex-direction: column; gap: 10px; flex: 1; }
.board-card__file {
  font-size: 0.8rem;
  color: var(--text-mid);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.chips { display: flex; flex-wrap: wrap; gap: 6px; }
.chip {
  padding: 3px 10px;
  border-radius: 99px;
  font-size: 0.775rem;
  font-weight: 580;
  border: 1px solid transparent;
}
.chip--missing { background: var(--missing-soft); color: var(--missing); border-color: color-mix(in srgb, var(--missing) 32%, transparent); }
.chip--review  { background: var(--review-soft);  color: var(--review);  border-color: color-mix(in srgb, var(--review) 32%, transparent); }
.chip--muted   { background: var(--surface-3);    color: var(--text-dim); }

.board-card__foot {
  margin-top: auto;
  display: flex;
  justify-content: space-between;
  gap: 10px;
  padding-top: 10px;
  border-top: 1px solid var(--border-soft);
  color: var(--text-dim);
  font-size: 0.73rem;
  font-variant-numeric: tabular-nums;
}

.empty-state { padding: 60px 20px; text-align: center; color: var(--text-dim); }
.empty-state__art {
  width: 72px; height: 72px;
  margin-bottom: 14px;
  fill: none; stroke: currentColor;
  stroke-width: 2.2; stroke-linecap: round; stroke-linejoin: round;
  opacity: 0.4;
}

/* --------------------------------------------------------------------------
   12. Detail dialog
   -------------------------------------------------------------------------- */

dialog { color: var(--text); }
dialog::backdrop { background: rgba(3, 6, 11, 0.68); backdrop-filter: blur(5px); }

.detail {
  width: min(1420px, 95vw);
  max-width: none;
  height: min(92vh, 980px);
  max-height: none;
  padding: 0;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  background: var(--surface-1);
  box-shadow: var(--shadow-3);
  overflow: hidden;
}
.detail[open] { display: flex; flex-direction: column; animation: dialog-in 0.28s var(--ease-out); }
@keyframes dialog-in {
  from { opacity: 0; transform: translateY(16px) scale(0.985); }
  to   { opacity: 1; transform: none; }
}

.detail__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 15px 18px;
  border-bottom: 1px solid var(--border);
  background: var(--surface-2);
}
.detail__sub { color: var(--text-dim); font-size: 0.8rem; margin-top: 2px; }

.detail__body {
  flex: 1;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 376px;
  min-height: 0;
}
@media (max-width: 1080px) { .detail__body { grid-template-columns: 1fr; overflow-y: auto; } }

.detail__stage { display: flex; flex-direction: column; min-width: 0; min-height: 0; }

.viewer {
  position: relative;
  flex: 1;
  min-height: 300px;
  background:
    linear-gradient(var(--border-soft) 1px, transparent 1px) 0 0 / 28px 28px,
    linear-gradient(90deg, var(--border-soft) 1px, transparent 1px) 0 0 / 28px 28px,
    var(--canvas-bg);
  overflow: hidden;
  touch-action: none;
}
.viewer canvas { display: block; width: 100%; height: 100%; }

.compare-handle {
  position: absolute;
  top: 0; bottom: 0;
  width: 2px;
  background: rgba(255, 255, 255, 0.92);
  box-shadow: 0 0 14px rgba(0, 0, 0, 0.55);
  cursor: ew-resize;
  transform: translateX(-1px);
}
.compare-handle__grip {
  position: absolute;
  top: 50%; left: 50%;
  width: 38px; height: 38px;
  transform: translate(-50%, -50%);
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.95);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.45);
}
.compare-handle__grip::before, .compare-handle__grip::after {
  content: "";
  position: absolute;
  top: 50%;
  width: 0; height: 0;
  border-top: 5px solid transparent;
  border-bottom: 5px solid transparent;
  transform: translateY(-50%);
}
.compare-handle__grip::before { left: 9px; border-right: 7px solid #10151d; }
.compare-handle__grip::after { right: 9px; border-left: 7px solid #10151d; }

.compare-handle__tag {
  position: absolute;
  top: 14px;
  padding: 4px 11px;
  border-radius: 99px;
  background: rgba(8, 12, 18, 0.82);
  color: #fff;
  font-size: 0.73rem;
  font-weight: 580;
  white-space: nowrap;
  backdrop-filter: blur(8px);
}
.compare-handle__tag--l { right: 12px; }
.compare-handle__tag--r { left: 12px; }

.legend {
  display: flex;
  gap: 20px;
  padding: 10px 18px;
  border-top: 1px solid var(--border);
  background: var(--surface-2);
  color: var(--text-mid);
  font-size: 0.78rem;
}
.legend span { display: flex; align-items: center; gap: 7px; }
.dot { width: 9px; height: 9px; border-radius: 50%; display: inline-block; }
.dot--ok { background: var(--ok); }
.dot--review { background: var(--review); }
.dot--missing { background: var(--missing); }

.detail__side {
  border-left: 1px solid var(--border);
  background: var(--surface-1);
  overflow-y: auto;
  padding: 18px;
}
@media (max-width: 1080px) { .detail__side { border-left: 0; border-top: 1px solid var(--border); } }

.verdict {
  padding: 16px 18px;
  border-radius: var(--radius);
  margin-bottom: 14px;
}
.verdict h3 { font-size: 1.4rem; letter-spacing: -0.028em; }
.verdict p { margin-top: 4px; font-size: 0.85rem; opacity: 0.92; }
.verdict--ok      { background: var(--ok-soft);      color: var(--ok); }
.verdict--review  { background: var(--review-soft);  color: var(--review); }
.verdict--missing { background: var(--missing-soft); color: var(--missing); }

.diagnostics { display: grid; gap: 7px; margin-bottom: 20px; }
.diag-row {
  display: flex;
  justify-content: space-between;
  gap: 14px;
  font-size: 0.79rem;
}
.diag-row dt { color: var(--text-dim); }
.diag-row dd { margin: 0; font-variant-numeric: tabular-nums; font-weight: 540; }

.warn-note {
  display: flex;
  gap: 9px;
  padding: 10px 12px;
  margin-bottom: 14px;
  border-radius: 10px;
  border: 1px solid color-mix(in srgb, var(--review) 30%, transparent);
  background: var(--review-soft);
  color: var(--text-mid);
  font-size: 0.79rem;
  line-height: 1.45;
}
.warn-note svg { width: 15px; height: 15px; flex: none; margin-top: 2px; fill: none; stroke: var(--review); stroke-width: 2; stroke-linecap: round; }

.side-title {
  font-size: 0.73rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-dim);
  margin-bottom: 9px;
}

.verdict-list { margin: 0; padding: 0; list-style: none; display: grid; gap: 5px; }

.vrow {
  border-radius: 10px;
  border: 1px solid transparent;
  overflow: hidden;
  transition: background 0.14s var(--ease), border-color 0.14s var(--ease);
}
.vrow:hover { background: var(--surface-2); }
.vrow.is-open { background: var(--surface-2); border-color: var(--border); }

.vrow__head {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 9px 11px;
  border: 0;
  background: none;
  text-align: left;
}
.vrow__dot { width: 8px; height: 8px; border-radius: 50%; flex: none; }
.vrow__name { flex: 1; font-size: 0.86rem; font-weight: 560; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.vrow__state { font-size: 0.73rem; font-weight: 620; text-transform: uppercase; letter-spacing: 0.05em; }
.vrow--present .vrow__dot { background: var(--ok); }
.vrow--review  .vrow__dot { background: var(--review); }
.vrow--missing .vrow__dot { background: var(--missing); }
.vrow--present .vrow__state { color: var(--text-dim); }
.vrow--review  .vrow__state { color: var(--review); }
.vrow--missing .vrow__state { color: var(--missing); }

.vrow__body { padding: 0 11px 12px; display: none; }
.vrow.is-open .vrow__body { display: block; animation: panel-in 0.22s var(--ease-out); }

.vrow__reason { color: var(--text-mid); font-size: 0.8rem; margin-bottom: 11px; line-height: 1.5; }

.crops { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-bottom: 12px; }
.crop { border-radius: 9px; border: 1px solid var(--border); overflow: hidden; background: var(--canvas-bg); }
.crop img { display: block; width: 100%; height: auto; image-rendering: crisp-edges; }
.crop figcaption {
  padding: 4px 8px;
  background: var(--surface-3);
  color: var(--text-dim);
  font-size: 0.68rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.evidence { display: grid; gap: 6px; }
.ev-row { display: grid; grid-template-columns: 96px 1fr 38px; align-items: center; gap: 9px; font-size: 0.74rem; }
.ev-row__label { color: var(--text-dim); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.ev-row__track { height: 5px; border-radius: 99px; background: var(--surface-3); overflow: hidden; }
.ev-row__fill { display: block; height: 100%; border-radius: 99px; background: var(--brand); transition: width 0.4s var(--ease-out); }
.ev-row__value { text-align: right; font-variant-numeric: tabular-nums; color: var(--text-mid); }

.confidence-bar { margin-bottom: 11px; }
.confidence-bar__track { height: 6px; border-radius: 99px; background: var(--surface-3); overflow: hidden; position: relative; }
.confidence-bar__fill { display: block; height: 100%; border-radius: 99px; transition: width 0.4s var(--ease-out); }
.confidence-bar__mark { position: absolute; top: -3px; bottom: -3px; width: 2px; background: var(--text-dim); opacity: 0.55; }
.confidence-bar__legend { display: flex; justify-content: space-between; margin-top: 5px; font-size: 0.7rem; color: var(--text-dim); font-variant-numeric: tabular-nums; }

/* --------------------------------------------------------------------------
   13. About sheet
   -------------------------------------------------------------------------- */

.sheet {
  width: min(560px, 92vw);
  padding: 26px;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  background: var(--surface-1);
  box-shadow: var(--shadow-3);
}
.sheet[open] { animation: dialog-in 0.26s var(--ease-out); }
.sheet__lead { margin: 10px 0 20px; color: var(--text-mid); font-size: 0.9rem; }
.sheet h3 { margin: 18px 0 9px; font-size: 0.73rem; text-transform: uppercase; letter-spacing: 0.08em; color: var(--text-dim); }
.sheet__steps { margin: 0; padding-left: 20px; color: var(--text-mid); font-size: 0.86rem; }
.sheet__steps li { margin-bottom: 5px; }
.sheet__keys { width: 100%; border-collapse: collapse; font-size: 0.84rem; }
.sheet__keys td { padding: 6px 0; border-bottom: 1px solid var(--border-soft); color: var(--text-mid); }
.sheet__keys td:first-child { width: 170px; white-space: nowrap; }
.sheet .row { margin-top: 22px; }

/* --------------------------------------------------------------------------
   14. Toasts
   -------------------------------------------------------------------------- */

.toasts {
  position: fixed;
  right: 20px;
  bottom: 20px;
  z-index: 90;
  display: flex;
  flex-direction: column;
  gap: 9px;
  pointer-events: none;
}

.toast {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  max-width: 400px;
  padding: 12px 15px;
  border-radius: var(--radius);
  border: 1px solid var(--border);
  background: var(--surface-up);
  box-shadow: var(--shadow-3);
  font-size: 0.855rem;
  pointer-events: auto;
  animation: toast-in 0.3s var(--ease-out);
}
@keyframes toast-in {
  from { opacity: 0; transform: translateX(22px) scale(0.97); }
  to   { opacity: 1; transform: none; }
}
.toast.is-leaving { animation: toast-out 0.22s var(--ease) forwards; }
@keyframes toast-out {
  to { opacity: 0; transform: translateX(22px) scale(0.97); }
}
.toast__bar { width: 3px; align-self: stretch; border-radius: 99px; flex: none; background: var(--brand); }
.toast--error .toast__bar { background: var(--missing); }
.toast--success .toast__bar { background: var(--ok); }
.toast--warn .toast__bar { background: var(--review); }
.toast__text { min-width: 0; }
.toast__text b { display: block; font-weight: 620; margin-bottom: 1px; }
.toast__text span { color: var(--text-mid); font-size: 0.82rem; line-height: 1.45; }

/* --------------------------------------------------------------------------
   15. Print — the inspection record
   -------------------------------------------------------------------------- */

@media print {
  .aurora, .appbar, .dropzone, .toasts, .panel__head .row { display: none !important; }
  body { background: #fff; color: #000; }
  .board-card { break-inside: avoid; box-shadow: none; border: 1px solid #999; }
  .results { grid-template-columns: 1fr 1fr; }
}

