    for (const bbox of boxes) {
      index += 1;
      this.parts.push({ id: makeId(), name: `${namePrefix} ${index}`, bbox: bbox.map(Math.round) });
    }
    this._emit();
  }

  renamePart(id, name) {
    const part = this.parts.find((p) => p.id === id);
    if (!part || part.name === name) return;
    this._snapshot();
    part.name = name;
    this._emit();
  }

  deletePart(id) {
