/**
 * Inspection results: summary strip, board cards, and the detail inspector.
 *
 * The verdict is shown three times at decreasing distance, because three
 * different people read it: the card banner answers "is this board good?"
 * across the room, the part list answers "which part?", and the expanded row
 * answers "why should I believe you?" with the two crops side by side and the
 * evidence that produced the number. The last one is what earns the operator's
 * trust the first time the tool disagrees with them.
 */

import { CanvasView, drawLabel, roundedRectPath } from './view.js';
import { loadImage, stateColour, formatTime, downloadBlob } from './ui.js';

const STATE_LABEL = { present: 'Present', review: 'Review', missing: 'Missing' };

const ICONS = {
  ok: '<path d="M4 12.5 9.5 18 20 6.5"/>',
  review: '<path d="M12 8v5.5M12 17.2v.1"/><path d="M10.3 3.9 2.6 17.4A2 2 0 0 0 4.3 20.4h15.4a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0Z"/>',
  missing: '<circle cx="12" cy="12" r="8.6"/><path d="M8.8 8.8l6.4 6.4M15.2 8.8l-6.4 6.4"/>',
};

const bannerKind = (status) => (status === 'present' ? 'ok' : status);

/* -------------------------------------------------------------------------
   Overlay rendering
   ------------------------------------------------------------------------- */

/**
 * Draw the board with its verdict boxes at the image's own resolution.
 * Used for card thumbnails and for the exported report.
 */
export function renderOverlayCanvas(image, verdicts, { lineScale = 1 } = {}) {
  const canvas = document.createElement('canvas');
  canvas.width = image.naturalWidth;
  canvas.height = image.naturalHeight;
  const ctx = canvas.getContext('2d');
  ctx.drawImage(image, 0, 0);

  const base = Math.max(canvas.width, canvas.height) / 600;
  const lineWidth = Math.max(1.6, base * 2.1 * lineScale);

  // Present parts first so that a missing box is never hidden under a
  // neighbouring green one.
  const ordered = [...verdicts].sort(
    (a, b) => (a.state === 'present' ? 0 : 1) - (b.state === 'present' ? 0 : 1),
  );

  for (const verdict of ordered) {
    const [x, y, w, h] = verdict.bbox;
    const colour = stateColour(verdict.state);
    ctx.save();
    roundedRectPath(ctx, x, y, w, h, 3 * base);
    if (verdict.state !== 'present') {
      ctx.fillStyle = colour.replace(')', ', 0.22)').replace('rgb', 'rgba');
      ctx.globalAlpha = 0.25;
      ctx.fillStyle = colour;
      ctx.fill();
      ctx.globalAlpha = 1;
    }
    ctx.lineWidth = verdict.state === 'present' ? lineWidth * 0.62 : lineWidth;
    ctx.strokeStyle = colour;
    ctx.stroke();
    ctx.restore();

    if (verdict.state !== 'present') {
      drawLabel(ctx, verdict.name, x, y, colour, {
        fontSize: Math.max(11, base * 11),
        canvasWidth: canvas.width,
      });
    }
  }
  return canvas;
}

/* -------------------------------------------------------------------------
   Batch summary + cards
   ------------------------------------------------------------------------- */

export function renderBatchSummary(host, batch) {
  host.classList.remove('is-hidden');
  host.innerHTML = `
    <div class="stat">
      <span class="stat__value">${batch.count}</span>
      <span class="stat__label">Boards checked</span>
    </div>
    <span class="stat__sep"></span>
    <div class="stat stat--ok">
      <span class="stat__value">${batch.ok_count}</span>
      <span class="stat__label">Complete</span>
    </div>
    <span class="stat__sep"></span>
    <div class="stat stat--missing">
      <span class="stat__value">${batch.missing_boards}</span>
      <span class="stat__label">With missing parts</span>
    </div>
    <span class="stat__sep"></span>
    <div class="stat">
      <span class="stat__value">${batch.total_missing_parts}</span>
      <span class="stat__label">Parts missing in total</span>
    </div>`;
}

export async function renderCards(host, results, onOpen) {
  for (const [index, result] of results.entries()) {
    const card = document.createElement('article');
    card.className = 'board-card';
    card.style.animationDelay = `${Math.min(index * 60, 360)}ms`;
    card.tabIndex = 0;
    card.setAttribute('role', 'button');

    const { status, headline, missing_names: missing, review_names: review } = result.summary;
    const kind = bannerKind(status);

    const chips = [
      ...missing.map((name) => `<span class="chip chip--missing">${escapeHtml(name)}</span>`),
      ...review.map((name) => `<span class="chip chip--review">${escapeHtml(name)}</span>`),
    ];
    if (!chips.length) {
      chips.push(`<span class="chip chip--muted">${result.summary.total_parts} parts verified</span>`);
    }

    card.innerHTML = `
      <div class="board-card__media"><canvas></canvas></div>
      <div class="board-card__banner banner--${kind}">
        <svg viewBox="0 0 24 24" aria-hidden="true">${ICONS[kind]}</svg>
        <span>${escapeHtml(headline)}</span>
      </div>
      <div class="board-card__body">
        <p class="board-card__file" title="${escapeHtml(result.filename)}">${escapeHtml(result.filename)}</p>
        <div class="chips">${chips.join('')}</div>
        <div class="board-card__foot">
          <span>Alignment ${(result.alignment.quality * 100).toFixed(0)}%</span>
          <span>${result.elapsed_ms.toFixed(0)} ms</span>
        </div>
      </div>`;

    card.addEventListener('click', () => onOpen(result));
    card.addEventListener('keydown', (event) => {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        onOpen(result);
      }
    });

    host.prepend(card);

    // Paint the thumbnail after the card is in the DOM so the layout settles
    // first and the cards appear immediately rather than after every decode.
    loadImage(result.images.test)
      .then((image) => {
        const source = renderOverlayCanvas(image, result.verdicts);
        const target = card.querySelector('canvas');
        const ratio = window.devicePixelRatio || 1;
        const box = target.getBoundingClientRect();
        target.width = Math.round(box.width * ratio);
        target.height = Math.round(box.height * ratio);
        const ctx = target.getContext('2d');
        const scale = Math.min(target.width / source.width, target.height / source.height);
        const w = source.width * scale;
        const h = source.height * scale;
        ctx.drawImage(source, (target.width - w) / 2, (target.height - h) / 2, w, h);
        result._overlay = source;
      })
      .catch(() => { /* thumbnail is cosmetic; the verdict is already shown */ });
  }
}

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (c) => (
    { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]
  ));
}

/* -------------------------------------------------------------------------
   Detail inspector
   ------------------------------------------------------------------------- */

export class DetailView {
  constructor(dialog) {
    this.dialog = dialog;
    this.canvas = dialog.querySelector('#detail-canvas');
    this.host = dialog.querySelector('#viewer');
    this.handle = dialog.querySelector('#compare-handle');
    this.view = new CanvasView(this.canvas, this.host);
    this.view.onChange = () => this.draw();

    this.result = null;
    this.images = null;
    this.mode = 'overlay';
    this.split = 0.5;
    this.hovered = null;

    this._bind();
  }

  _bind() {
    dialogCloseOn(this.dialog, this.dialog.querySelector('#detail-close'));

    this.dialog.querySelector('#detail-view').addEventListener('click', (event) => {
      const button = event.target.closest('button[data-view]');
      if (!button) return;
      this.setMode(button.dataset.view);
    });

    // --- viewer pan / zoom ---
    let panning = null;
    this.canvas.addEventListener('pointerdown', (event) => {
      this.canvas.setPointerCapture(event.pointerId);
      panning = { x: event.clientX, y: event.clientY };
      this.canvas.style.cursor = 'grabbing';
    });
    this.canvas.addEventListener('pointermove', (event) => {
      if (!panning) return;
      this.view.panBy(event.clientX - panning.x, event.clientY - panning.y);
      panning = { x: event.clientX, y: event.clientY };
    });
    const endPan = () => { panning = null; this.canvas.style.cursor = 'grab'; };
    this.canvas.addEventListener('pointerup', endPan);
    this.canvas.addEventListener('pointercancel', endPan);
    this.canvas.style.cursor = 'grab';

    this.canvas.addEventListener('wheel', (event) => {
      event.preventDefault();
      const point = this.view.pointer(event);
      this.view.zoomAt(Math.exp(-event.deltaY * 0.0022), point.x, point.y);
    }, { passive: false });

    // --- compare slider ---
    let dragging = false;
    const move = (event) => {
      if (!dragging) return;
      const rect = this.host.getBoundingClientRect();
      this.split = Math.min(1, Math.max(0, (event.clientX - rect.left) / rect.width));
      this.positionHandle();
      this.draw();
    };
    this.handle.addEventListener('pointerdown', (event) => {
      dragging = true;
      this.handle.setPointerCapture(event.pointerId);
      event.stopPropagation();
    });
    this.handle.addEventListener('pointermove', move);
    this.handle.addEventListener('pointerup', () => { dragging = false; });
  }

  async open(result) {
    this.result = result;
    this.mode = 'overlay';
    this.split = 0.5;
    this.hovered = null;

    this.dialog.querySelector('#detail-title').textContent = result.filename;
    this.dialog.querySelector('#detail-sub').textContent =
      `Inspected ${formatTime(result.created_at)} · ${result.summary.total_parts} parts · `
      + `${result.sensitivity} sensitivity`;

    this._syncModeButtons();
    this.renderSide();

    if (!this.dialog.open) this.dialog.showModal();

    this.images = {
      test: await loadImage(result.images.aligned),
      reference: await loadImage(result.images.reference),
    };

    this.view.resize();
    this.view.setContent(this.images.test.naturalWidth, this.images.test.naturalHeight);
    this.view.fit(16);
    this.positionHandle();
    this.draw();
  }

  setMode(mode) {
    this.mode = mode;
    this._syncModeButtons();
    this.handle.classList.toggle('is-hidden', mode !== 'compare');
    this.positionHandle();
    this.draw();
  }

  _syncModeButtons() {
    for (const button of this.dialog.querySelectorAll('#detail-view button')) {
      button.classList.toggle('is-active', button.dataset.view === this.mode);
    }
    this.handle.classList.toggle('is-hidden', this.mode !== 'compare');
  }

  positionHandle() {
    this.handle.style.left = `${this.split * 100}%`;
  }

  highlight(partId) {
    this.hovered = partId;
    this.draw();
  }

  focusPart(partId) {
    const verdict = this.result?.verdicts.find((v) => v.part_id === partId);
    if (!verdict) return;
    const [x, y, w, h] = verdict.bbox;
    this.view.focusOn(x, y, w, h, 140);
    this.highlight(partId);
  }

  draw() {
    if (!this.images) return;
    const { ctx, scale, tx, ty } = this.view;
    this.view.clear();

    const { test, reference } = this.images;
    const w = test.naturalWidth * scale;
    const h = test.naturalHeight * scale;

    if (this.mode === 'compare') {
      const splitX = this.split * this.view.width;

      ctx.save();
      ctx.beginPath();
      ctx.rect(0, 0, splitX, this.view.height);
      ctx.clip();
      ctx.drawImage(reference, tx, ty, w, h);
      ctx.restore();

      ctx.save();
      ctx.beginPath();
      ctx.rect(splitX, 0, this.view.width - splitX, this.view.height);
      ctx.clip();
      ctx.drawImage(test, tx, ty, w, h);
      ctx.restore();
    } else {
      ctx.imageSmoothingEnabled = scale <= 2;
      ctx.drawImage(test, tx, ty, w, h);
    }

    const ordered = [...this.result.verdicts].sort(
      (a, b) => (a.state === 'present' ? 0 : 1) - (b.state === 'present' ? 0 : 1),
    );

    for (const verdict of ordered) {
      const [bx, by, bw, bh] = verdict.bbox;
      const topLeft = this.view.toScreen(bx, by);
      const rect = { x: topLeft.x, y: topLeft.y, w: bw * scale, h: bh * scale };
      const colour = stateColour(verdict.state);
      const isHovered = this.hovered === verdict.part_id;

      ctx.save();
      roundedRectPath(ctx, rect.x, rect.y, rect.w, rect.h, 3);
      if (verdict.state !== 'present' || isHovered) {
        ctx.globalAlpha = isHovered ? 0.3 : 0.2;
        ctx.fillStyle = colour;
        ctx.fill();
        ctx.globalAlpha = 1;
      }
      ctx.lineWidth = isHovered ? 3 : verdict.state === 'present' ? 1.2 : 2;
      ctx.strokeStyle = colour;
      ctx.stroke();
      ctx.restore();

      if (verdict.state !== 'present' || isHovered) {
        drawLabel(ctx, verdict.name, rect.x, rect.y, colour, { canvasWidth: this.view.width });
      }
    }
  }

  renderSide() {
    const result = this.result;
    const { status, headline } = result.summary;
    const kind = bannerKind(status);

    const verdictBox = this.dialog.querySelector('#detail-verdict');
    verdictBox.className = `verdict verdict--${kind}`;
    verdictBox.innerHTML = `
      <h3>${escapeHtml(headline)}</h3>
      <p>${
        status === 'present'
          ? 'Every named part was found on this board.'
          : status === 'missing'
            ? `Missing: ${result.summary.missing_names.map(escapeHtml).join(', ')}`
            : `Please check: ${result.summary.review_names.map(escapeHtml).join(', ')}`
      }</p>`;

    const alignment = result.alignment;
    const sharpness = result.sharpness || {};
    const warnings = (result.warnings || [])
      .map((text) => `
        <div class="warn-note">
          <svg viewBox="0 0 24 24"><path d="M12 8v5.5M12 17.2v.1"/><path d="M10.3 3.9 2.6 17.4A2 2 0 0 0 4.3 20.4h15.4a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0Z"/></svg>
          <span>${escapeHtml(text)}</span>
        </div>`)
      .join('');

    this.dialog.querySelector('#detail-diagnostics').innerHTML = `
      ${warnings}
      <dl class="diag-row"><dt>Alignment quality</dt><dd>${(alignment.quality * 100).toFixed(0)}%</dd></dl>
      <dl class="diag-row"><dt>Method</dt><dd>${escapeHtml(alignment.method.toUpperCase())}</dd></dl>
      <dl class="diag-row"><dt>Shift corrected</dt><dd>${alignment.translation_px.toFixed(1)} px · ${alignment.rotation_deg.toFixed(2)}°</dd></dl>
      <dl class="diag-row"><dt>Exposure correction</dt><dd>×${(result.photometric.gain ?? 1).toFixed(2)}</dd></dl>
      ${sharpness.sigma ? `<dl class="diag-row"><dt>Focus equalised</dt><dd>σ ${sharpness.sigma.toFixed(2)} px</dd></dl>` : ''}
      ${result.scene_compensation > 0.01 ? `<dl class="diag-row"><dt>Scene compensation</dt><dd>−${result.scene_compensation.toFixed(2)}</dd></dl>` : ''}
      <dl class="diag-row"><dt>Processing time</dt><dd>${result.elapsed_ms.toFixed(0)} ms</dd></dl>`;

    const list = this.dialog.querySelector('#verdict-list');
    list.innerHTML = '';

    const order = { missing: 0, review: 1, present: 2 };
    const sorted = [...result.verdicts].sort(
      (a, b) => order[a.state] - order[b.state] || b.confidence - a.confidence,
    );

    for (const verdict of sorted) {
      list.appendChild(this._verdictRow(verdict));
    }
  }

  _verdictRow(verdict) {
    const item = document.createElement('li');
    item.className = `vrow vrow--${verdict.state}`;

    const thresholds = this.result.thresholds;
    const colour = stateColour(verdict.state);

    const evidence = verdict.evidence
      .map((channel) => `
        <div class="ev-row">
          <span class="ev-row__label">${escapeHtml(channel.label)}</span>
          <span class="ev-row__track">
            <span class="ev-row__fill" style="width:${(channel.score * 100).toFixed(0)}%;background:${colour}"></span>
          </span>
          <span class="ev-row__value">${channel.score.toFixed(2)}</span>
        </div>`)
      .join('');

    item.innerHTML = `
      <button class="vrow__head" type="button">
        <span class="vrow__dot"></span>
        <span class="vrow__name">${escapeHtml(verdict.name)}</span>
        <span class="vrow__state">${STATE_LABEL[verdict.state]}</span>
      </button>
      <div class="vrow__body">
        <p class="vrow__reason">${escapeHtml(verdict.reason)}</p>
        <div class="confidence-bar">
          <div class="confidence-bar__track">
            <span class="confidence-bar__fill" style="width:${(verdict.confidence * 100).toFixed(0)}%;background:${colour}"></span>
            <span class="confidence-bar__mark" style="left:${(thresholds.review * 100).toFixed(0)}%"></span>
            <span class="confidence-bar__mark" style="left:${(thresholds.missing * 100).toFixed(0)}%"></span>
          </div>
          <div class="confidence-bar__legend">
            <span>confidence ${verdict.confidence.toFixed(2)}</span>
            <span>flags at ${thresholds.missing.toFixed(2)}</span>
          </div>
        </div>
        <div class="crops">
          <figure class="crop">
            <img loading="lazy" alt="Reference crop of ${escapeHtml(verdict.name)}"
                 src="/api/runs/${this.result.run_id}/crop/${verdict.part_id}/reference.png">
            <figcaption>Reference</figcaption>
          </figure>
          <figure class="crop">
            <img loading="lazy" alt="This board at ${escapeHtml(verdict.name)}"
                 src="/api/runs/${this.result.run_id}/crop/${verdict.part_id}/test.png">
            <figcaption>This board</figcaption>
          </figure>
        </div>
        <div class="evidence">${evidence}</div>
      </div>`;

    const head = item.querySelector('.vrow__head');
    head.addEventListener('click', () => {
      const open = item.classList.toggle('is-open');
      if (open) this.focusPart(verdict.part_id);
    });
    item.addEventListener('mouseenter', () => this.highlight(verdict.part_id));
    item.addEventListener('mouseleave', () => this.highlight(null));

    // Missing parts start expanded: that is the row the operator opened the
    // dialog to read, and making them click again to see the proof is friction
    // at exactly the wrong moment.
    if (verdict.state === 'missing') item.classList.add('is-open');

    return item;
  }
}

function dialogCloseOn(dialog, button) {
  button.addEventListener('click', () => dialog.close());
  dialog.addEventListener('click', (event) => {
    // Clicking the backdrop (outside the dialog's own box) closes it.
    const rect = dialog.getBoundingClientRect();
    const inside =
      event.clientX >= rect.left && event.clientX <= rect.right &&
      event.clientY >= rect.top && event.clientY <= rect.bottom;
    if (!inside) dialog.close();
  });
}

/* -------------------------------------------------------------------------
   Offline report
   ------------------------------------------------------------------------- */

/**
 * Build a single self-contained HTML file with the images inlined.
 *
 * A report that referenced /api/... would be blank the moment the server
 * stopped, which is precisely when someone wants to read it. Inlining keeps
 * it readable on any machine, forever, with no application at all.
 */
export async function buildReport(results, projectName) {
  const sections = [];

  for (const result of results) {
    const image = result._overlay || renderOverlayCanvas(
      await loadImage(result.images.test), result.verdicts,
    );
    const dataUrl = image.toDataURL('image/jpeg', 0.82);
    const { status, headline } = result.summary;

    const rows = result.verdicts
      .slice()
      .sort((a, b) => b.confidence - a.confidence)
      .map((verdict) => `
        <tr class="s-${verdict.state}">
          <td>${escapeHtml(verdict.name)}</td>
          <td>${STATE_LABEL[verdict.state]}</td>
          <td>${verdict.confidence.toFixed(3)}</td>
          <td>${escapeHtml(verdict.reason)}</td>
        </tr>`)
      .join('');

    sections.push(`
      <section>
        <h2 class="s-${status}">${escapeHtml(result.filename)} — ${escapeHtml(headline)}</h2>
        <p class="meta">
          Inspected ${new Date(result.created_at * 1000).toLocaleString()} ·
          sensitivity ${escapeHtml(result.sensitivity)} ·
          alignment ${(result.alignment.quality * 100).toFixed(0)}% ·
          ${result.elapsed_ms.toFixed(0)} ms
        </p>
        <img src="${dataUrl}" alt="Inspected board">
        <table>
          <thead><tr><th>Part</th><th>State</th><th>Confidence</th><th>Reason</th></tr></thead>
          <tbody>${rows}</tbody>
        </table>
      </section>`);
  }

  const html = `<!doctype html>
<html lang="en"><head><meta charset="utf-8">
<title>Inspection report — ${escapeHtml(projectName)}</title>
<style>
  body{font:15px/1.6 -apple-system,"Segoe UI",Roboto,sans-serif;margin:0;padding:40px;
       background:#f6f8fb;color:#101722;max-width:980px;margin-inline:auto}
  h1{font-size:1.7rem;margin:0 0 4px}
  .lead{color:#5b6b80;margin:0 0 32px}
  section{background:#fff;border:1px solid #e2e8f0;border-radius:14px;padding:22px;margin-bottom:22px}
  h2{font-size:1.1rem;margin:0 0 4px}
  .meta{color:#6b7c93;font-size:.82rem;margin:0 0 14px}
  img{width:100%;border-radius:10px;border:1px solid #e2e8f0;display:block;margin-bottom:16px}
  table{width:100%;border-collapse:collapse;font-size:.86rem}
  th{text-align:left;color:#6b7c93;font-weight:600;border-bottom:2px solid #e2e8f0;padding:7px 8px}
  td{padding:7px 8px;border-bottom:1px solid #eef2f7}
  .s-missing{color:#d12c43}.s-review{color:#b26a00}.s-present{color:#0f8f52}
  h2.s-present{color:#0f8f52}h2.s-missing{color:#d12c43}h2.s-review{color:#b26a00}
  footer{color:#8494a8;font-size:.78rem;text-align:center;margin-top:30px}
</style></head>
<body>
  <h1>Inspection report</h1>
  <p class="lead">${escapeHtml(projectName)} · generated ${new Date().toLocaleString()}</p>
  ${sections.join('')}
  <footer>Produced offline by PCB Inspector. Images are embedded in this file.</footer>
</body></html>`;

  downloadBlob(
    new Blob([html], { type: 'text/html' }),
    `inspection-report-${new Date().toISOString().slice(0, 10)}.html`,
  );
}

toolu_01U57caxB43EtFy3wQ6fbKww.content:
/**
 * Inspection results: summary strip, board cards, and the detail inspector.
 *
 * The verdict is shown three times at decreasing distance, because three
 * different people read it: the card banner answers "is this board good?"
 * across the room, the part list answers "which part?", and the expanded row
 * answers "why should I believe you?" with the two crops side by side and the
 * evidence that produced the number. The last one is what earns the operator's
 * trust the first time the tool disagrees with them.
 */

import { CanvasView, drawLabel, roundedRectPath } from './view.js';
import { loadImage, stateColour, formatTime, downloadBlob } from './ui.js';

const STATE_LABEL = { present: 'Present', review: 'Review', missing: 'Missing' };

const ICONS = {
  ok: '<path d="M4 12.5 9.5 18 20 6.5"/>',
  review: '<path d="M12 8v5.5M12 17.2v.1"/><path d="M10.3 3.9 2.6 17.4A2 2 0 0 0 4.3 20.4h15.4a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0Z"/>',
  missing: '<circle cx="12" cy="12" r="8.6"/><path d="M8.8 8.8l6.4 6.4M15.2 8.8l-6.4 6.4"/>',
};

const bannerKind = (status) => (status === 'present' ? 'ok' : status);

/* -------------------------------------------------------------------------
   Overlay rendering
   ------------------------------------------------------------------------- */

/**
 * Draw the board with its verdict boxes at the image's own resolution.
 * Used for card thumbnails and for the exported report.
 */
export function renderOverlayCanvas(image, verdicts, { lineScale = 1 } = {}) {
  const canvas = document.createElement('canvas');
  canvas.width = image.naturalWidth;
  canvas.height = image.naturalHeight;
  const ctx = canvas.getContext('2d');
  ctx.drawImage(image, 0, 0);

  const base = Math.max(canvas.width, canvas.height) / 600;
  const lineWidth = Math.max(1.6, base * 2.1 * lineScale);

  // Present parts first so that a missing box is never hidden under a
  // neighbouring green one.
  const ordered = [...verdicts].sort(
    (a, b) => (a.state === 'present' ? 0 : 1) - (b.state === 'present' ? 0 : 1),
  );

  for (const verdict of ordered) {
    const [x, y, w, h] = verdict.bbox;
    const colour = stateColour(verdict.state);
    ctx.save();
    roundedRectPath(ctx, x, y, w, h, 3 * base);
    if (verdict.state !== 'present') {
      ctx.fillStyle = colour.replace(')', ', 0.22)').replace('rgb', 'rgba');
      ctx.globalAlpha = 0.25;
      ctx.fillStyle = colour;
      ctx.fill();
      ctx.globalAlpha = 1;
    }
    ctx.lineWidth = verdict.state === 'present' ? lineWidth * 0.62 : lineWidth;
    ctx.strokeStyle = colour;
    ctx.stroke();
    ctx.restore();

    if (verdict.state !== 'present') {
      drawLabel(ctx, verdict.name, x, y, colour, {
        fontSize: Math.max(11, base * 11),
        canvasWidth: canvas.width,
      });
    }
  }
  return canvas;
}

/* -------------------------------------------------------------------------
   Batch summary + cards
   ------------------------------------------------------------------------- */

export function renderBatchSummary(host, batch) {
  host.classList.remove('is-hidden');
  host.innerHTML = `
    <div class="stat">
      <span class="stat__value">${batch.count}</span>
      <span class="stat__label">Boards checked</span>
    </div>
    <span class="stat__sep"></span>
    <div class="stat stat--ok">
      <span class="stat__value">${batch.ok_count}</span>
      <span class="stat__label">Complete</span>
    </div>
    <span class="stat__sep"></span>
    <div class="stat stat--missing">
      <span class="stat__value">${batch.missing_boards}</span>
      <span class="stat__label">With missing parts</span>
    </div>
    <span class="stat__sep"></span>
    <div class="stat">
      <span class="stat__value">${batch.total_missing_parts}</span>
      <span class="stat__label">Parts missing in total</span>
    </div>`;
}

export async function renderCards(host, results, onOpen) {
  for (const [index, result] of results.entries()) {
    const card = document.createElement('article');
    card.className = 'board-card';
    card.style.animationDelay = `${Math.min(index * 60, 360)}ms`;
    card.tabIndex = 0;
    card.setAttribute('role', 'button');

    const { status, headline, missing_names: missing, review_names: review } = result.summary;
    const kind = bannerKind(status);

    const chips = [
      ...missing.map((name) => `<span class="chip chip--missing">${escapeHtml(name)}</span>`),
      ...review.map((name) => `<span class="chip chip--review">${escapeHtml(name)}</span>`),
    ];
    if (!chips.length) {
      chips.push(`<span class="chip chip--muted">${result.summary.total_parts} parts verified</span>`);
    }

    card.innerHTML = `
      <div class="board-card__media"><canvas></canvas></div>
      <div class="board-card__banner banner--${kind}">
        <svg viewBox="0 0 24 24" aria-hidden="true">${ICONS[kind]}</svg>
        <span>${escapeHtml(headline)}</span>
      </div>
      <div class="board-card__body">
        <p class="board-card__file" title="${escapeHtml(result.filename)}">${escapeHtml(result.filename)}</p>
        <div class="chips">${chips.join('')}</div>
        <div class="board-card__foot">
          <span>Alignment ${(result.alignment.quality * 100).toFixed(0)}%</span>
          <span>${result.elapsed_ms.toFixed(0)} ms</span>
        </div>
      </div>`;

    card.addEventListener('click', () => onOpen(result));
    card.addEventListener('keydown', (event) => {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        onOpen(result);
      }
    });

    host.prepend(card);

    // Paint the thumbnail after the card is in the DOM so the layout settles
    // first and the cards appear immediately rather than after every decode.
    loadImage(result.images.test)
      .then((image) => {
        const source = renderOverlayCanvas(image, result.verdicts);
        const target = card.querySelector('canvas');
        const ratio = window.devicePixelRatio || 1;
        const box = target.getBoundingClientRect();
        target.width = Math.round(box.width * ratio);
        target.height = Math.round(box.height * ratio);
        const ctx = target.getContext('2d');
        const scale = Math.min(target.width / source.width, target.height / source.height);
        const w = source.width * scale;
        const h = source.height * scale;
        ctx.drawImage(source, (target.width - w) / 2, (target.height - h) / 2, w, h);
        result._overlay = source;
      })
      .catch(() => { /* thumbnail is cosmetic; the verdict is already shown */ });
  }
}

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (c) => (
    { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]
  ));
}

/* -------------------------------------------------------------------------
   Detail inspector
   ------------------------------------------------------------------------- */

export class DetailView {
  constructor(dialog) {
    this.dialog = dialog;
    this.canvas = dialog.querySelector('#detail-canvas');
    this.host = dialog.querySelector('#viewer');
    this.handle = dialog.querySelector('#compare-handle');
    this.view = new CanvasView(this.canvas, this.host);
    this.view.onChange = () => this.draw();

    this.result = null;
    this.images = null;
    this.mode = 'overlay';
    this.split = 0.5;
    this.hovered = null;

    this._bind();
  }

  _bind() {
    dialogCloseOn(this.dialog, this.dialog.querySelector('#detail-close'));

    this.dialog.querySelector('#detail-view').addEventListener('click', (event) => {
      const button = event.target.closest('button[data-view]');
      if (!button) return;
      this.setMode(button.dataset.view);
    });

    // --- viewer pan / zoom ---
    let panning = null;
    this.canvas.addEventListener('pointerdown', (event) => {
      this.canvas.setPointerCapture(event.pointerId);
      panning = { x: event.clientX, y: event.clientY };
      this.canvas.style.cursor = 'grabbing';
    });
    this.canvas.addEventListener('pointermove', (event) => {
      if (!panning) return;
      this.view.panBy(event.clientX - panning.x, event.clientY - panning.y);
      panning = { x: event.clientX, y: event.clientY };
    });
    const endPan = () => { panning = null; this.canvas.style.cursor = 'grab'; };
    this.canvas.addEventListener('pointerup', endPan);
    this.canvas.addEventListener('pointercancel', endPan);
    this.canvas.style.cursor = 'grab';

    this.canvas.addEventListener('wheel', (event) => {
      event.preventDefault();
      const point = this.view.pointer(event);
      this.view.zoomAt(Math.exp(-event.deltaY * 0.0022), point.x, point.y);
    }, { passive: false });

    // --- compare slider ---
    let dragging = false;
    const move = (event) => {
      if (!dragging) return;
      const rect = this.host.getBoundingClientRect();
      this.split = Math.min(1, Math.max(0, (event.clientX - rect.left) / rect.width));
      this.positionHandle();
      this.draw();
    };
    this.handle.addEventListener('pointerdown', (event) => {
      dragging = true;
      this.handle.setPointerCapture(event.pointerId);
      event.stopPropagation();
    });
    this.handle.addEventListener('pointermove', move);
    this.handle.addEventListener('pointerup', () => { dragging = false; });
  }

  async open(result) {
    this.result = result;
    this.mode = 'overlay';
    this.split = 0.5;
    this.hovered = null;

    this.dialog.querySelector('#detail-title').textContent = result.filename;
    this.dialog.querySelector('#detail-sub').textContent =
      `Inspected ${formatTime(result.created_at)} · ${result.summary.total_parts} parts · `
      + `${result.sensitivity} sensitivity`;

    this._syncModeButtons();
    this.renderSide();

    if (!this.dialog.open) this.dialog.showModal();

    this.images = {
      test: await loadImage(result.images.aligned),
      reference: await loadImage(result.images.reference),
    };

    this.view.resize();
    this.view.setContent(this.images.test.naturalWidth, this.images.test.naturalHeight);
    this.view.fit(16);
    this.positionHandle();
    this.draw();
  }

  setMode(mode) {
    this.mode = mode;
    this._syncModeButtons();
    this.handle.classList.toggle('is-hidden', mode !== 'compare');
    this.positionHandle();
    this.draw();
  }

  _syncModeButtons() {
    for (const button of this.dialog.querySelectorAll('#detail-view button')) {
      button.classList.toggle('is-active', button.dataset.view === this.mode);
    }
    this.handle.classList.toggle('is-hidden', this.mode !== 'compare');
  }

  positionHandle() {
    this.handle.style.left = `${this.split * 100}%`;
  }

  highlight(partId) {
    this.hovered = partId;
    this.draw();
  }

  focusPart(partId) {
    const verdict = this.result?.verdicts.find((v) => v.part_id === partId);
    if (!verdict) return;
    const [x, y, w, h] = verdict.bbox;
    this.view.focusOn(x, y, w, h, 140);
    this.highlight(partId);
  }

  draw() {
    if (!this.images) return;
    const { ctx, scale, tx, ty } = this.view;
    this.view.clear();

    const { test, reference } = this.images;
    const w = test.naturalWidth * scale;
    const h = test.naturalHeight * scale;

    if (this.mode === 'compare') {
      const splitX = this.split * this.view.width;

      ctx.save();
      ctx.beginPath();
      ctx.rect(0, 0, splitX, this.view.height);
      ctx.clip();
      ctx.drawImage(reference, tx, ty, w, h);
      ctx.restore();

      ctx.save();
      ctx.beginPath();
      ctx.rect(splitX, 0, this.view.width - splitX, this.view.height);
      ctx.clip();
      ctx.drawImage(test, tx, ty, w, h);
      ctx.restore();
    } else {
      ctx.imageSmoothingEnabled = scale <= 2;
      ctx.drawImage(test, tx, ty, w, h);
    }

    const ordered = [...this.result.verdicts].sort(
      (a, b) => (a.state === 'present' ? 0 : 1) - (b.state === 'present' ? 0 : 1),
    );

    for (const verdict of ordered) {
      const [bx, by, bw, bh] = verdict.bbox;
      const topLeft = this.view.toScreen(bx, by);
      const rect = { x: topLeft.x, y: topLeft.y, w: bw * scale, h: bh * scale };
      const colour = stateColour(verdict.state);
      const isHovered = this.hovered === verdict.part_id;

      ctx.save();
      roundedRectPath(ctx, rect.x, rect.y, rect.w, rect.h, 3);
      if (verdict.state !== 'present' || isHovered) {
        ctx.globalAlpha = isHovered ? 0.3 : 0.2;
        ctx.fillStyle = colour;
        ctx.fill();
        ctx.globalAlpha = 1;
      }
      ctx.lineWidth = isHovered ? 3 : verdict.state === 'present' ? 1.2 : 2;
      ctx.strokeStyle = colour;
      ctx.stroke();
      ctx.restore();

      if (verdict.state !== 'present' || isHovered) {
        drawLabel(ctx, verdict.name, rect.x, rect.y, colour, { canvasWidth: this.view.width });
      }
    }
  }

  renderSide() {
    const result = this.result;
    const { status, headline } = result.summary;
    const kind = bannerKind(status);

    const verdictBox = this.dialog.querySelector('#detail-verdict');
    verdictBox.className = `verdict verdict--${kind}`;
    verdictBox.innerHTML = `
      <h3>${escapeHtml(headline)}</h3>
      <p>${
        status === 'present'
          ? 'Every named part was found on this board.'
          : status === 'missing'
            ? `Missing: ${result.summary.missing_names.map(escapeHtml).join(', ')}`
            : `Please check: ${result.summary.review_names.map(escapeHtml).join(', ')}`
      }</p>`;

    const alignment = result.alignment;
    const sharpness = result.sharpness || {};
    const warnings = (result.warnings || [])
      .map((text) => `
        <div class="warn-note">
          <svg viewBox="0 0 24 24"><path d="M12 8v5.5M12 17.2v.1"/><path d="M10.3 3.9 2.6 17.4A2 2 0 0 0 4.3 20.4h15.4a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0Z"/></svg>
          <span>${escapeHtml(text)}</span>
        </div>`)
      .join('');

    this.dialog.querySelector('#detail-diagnostics').innerHTML = `
      ${warnings}
      <dl class="diag-row"><dt>Alignment quality</dt><dd>${(alignment.quality * 100).toFixed(0)}%</dd></dl>
      <dl class="diag-row"><dt>Method</dt><dd>${escapeHtml(alignment.method.toUpperCase())}</dd></dl>
      <dl class="diag-row"><dt>Shift corrected</dt><dd>${alignment.translation_px.toFixed(1)} px · ${alignment.rotation_deg.toFixed(2)}°</dd></dl>
      <dl class="diag-row"><dt>Exposure correction</dt><dd>×${(result.photometric.gain ?? 1).toFixed(2)}</dd></dl>
      ${sharpness.sigma ? `<dl class="diag-row"><dt>Focus equalised</dt><dd>σ ${sharpness.sigma.toFixed(2)} px</dd></dl>` : ''}
      ${result.scene_compensation > 0.01 ? `<dl class="diag-row"><dt>Scene compensation</dt><dd>−${result.scene_compensation.toFixed(2)}</dd></dl>` : ''}
      <dl class="diag-row"><dt>Processing time</dt><dd>${result.elapsed_ms.toFixed(0)} ms</dd></dl>`;

    const list = this.dialog.querySelector('#verdict-list');
    list.innerHTML = '';

    const order = { missing: 0, review: 1, present: 2 };
    const sorted = [...result.verdicts].sort(
      (a, b) => order[a.state] - order[b.state] || b.confidence - a.confidence,
    );

    for (const verdict of sorted) {
      list.appendChild(this._verdictRow(verdict));
    }
  }

  _verdictRow(verdict) {
    const item = document.createElement('li');
    item.className = `vrow vrow--${verdict.state}`;

    const thresholds = this.result.thresholds;
    const colour = stateColour(verdict.state);

    const evidence = verdict.evidence
      .map((channel) => `
        <div class="ev-row">
          <span class="ev-row__label">${escapeHtml(channel.label)}</span>
          <span class="ev-row__track">
            <span class="ev-row__fill" style="width:${(channel.score * 100).toFixed(0)}%;background:${colour}"></span>
          </span>
          <span class="ev-row__value">${channel.score.toFixed(2)}</span>
        </div>`)
      .join('');

    item.innerHTML = `
      <button class="vrow__head" type="button">
        <span class="vrow__dot"></span>
        <span class="vrow__name">${escapeHtml(verdict.name)}</span>
        <span class="vrow__state">${STATE_LABEL[verdict.state]}</span>
      </button>
      <div class="vrow__body">
        <p class="vrow__reason">${escapeHtml(verdict.reason)}</p>
        <div class="confidence-bar">
          <div class="confidence-bar__track">
            <span class="confidence-bar__fill" style="width:${(verdict.confidence * 100).toFixed(0)}%;background:${colour}"></span>
            <span class="confidence-bar__mark" style="left:${(thresholds.review * 100).toFixed(0)}%"></span>
            <span class="confidence-bar__mark" style="left:${(thresholds.missing * 100).toFixed(0)}%"></span>
          </div>
          <div class="confidence-bar__legend">
            <span>confidence ${verdict.confidence.toFixed(2)}</span>
            <span>flags at ${thresholds.missing.toFixed(2)}</span>
          </div>
        </div>
        <div class="crops">
          <figure class="crop">
            <img loading="lazy" alt="Reference crop of ${escapeHtml(verdict.name)}"
                 src="/api/runs/${this.result.run_id}/crop/${verdict.part_id}/reference.png">
            <figcaption>Reference</figcaption>
          </figure>
          <figure class="crop">
            <img loading="lazy" alt="This board at ${escapeHtml(verdict.name)}"
                 src="/api/runs/${this.result.run_id}/crop/${verdict.part_id}/test.png">
            <figcaption>This board</figcaption>
          </figure>
        </div>
        <div class="evidence">${evidence}</div>
      </div>`;

    const head = item.querySelector('.vrow__head');
    head.addEventListener('click', () => {
      const open = item.classList.toggle('is-open');
      if (open) this.focusPart(verdict.part_id);
    });
    item.addEventListener('mouseenter', () => this.highlight(verdict.part_id));
    item.addEventListener('mouseleave', () => this.highlight(null));

    // Missing parts start expanded: that is the row the operator opened the
    // dialog to read, and making them click again to see the proof is friction
    // at exactly the wrong moment.
    if (verdict.state === 'missing') item.classList.add('is-open');

    return item;
  }
}

function dialogCloseOn(dialog, button) {
  button.addEventListener('click', () => dialog.close());
  dialog.addEventListener('click', (event) => {
    // Clicking the backdrop (outside the dialog's own box) closes it.
    const rect = dialog.getBoundingClientRect();
    const inside =
      event.clientX >= rect.left && event.clientX <= rect.right &&
      event.clientY >= rect.top && event.clientY <= rect.bottom;
    if (!inside) dialog.close();
  });
}

/* -------------------------------------------------------------------------
   Offline report
   ------------------------------------------------------------------------- */

/**
 * Build a single self-contained HTML file with the images inlined.
 *
 * A report that referenced /api/... would be blank the moment the server
 * stopped, which is precisely when someone wants to read it. Inlining keeps
 * it readable on any machine, forever, with no application at all.
 */
export async function buildReport(results, projectName) {
  const sections = [];

  for (const result of results) {
    const image = result._overlay || renderOverlayCanvas(
      await loadImage(result.images.test), result.verdicts,
    );
    const dataUrl = image.toDataURL('image/jpeg', 0.82);
    const { status, headline } = result.summary;

    const rows = result.verdicts
      .slice()
      .sort((a, b) => b.confidence - a.confidence)
      .map((verdict) => `
        <tr class="s-${verdict.state}">
          <td>${escapeHtml(verdict.name)}</td>
          <td>${STATE_LABEL[verdict.state]}</td>
          <td>${verdict.confidence.toFixed(3)}</td>
          <td>${escapeHtml(verdict.reason)}</td>
        </tr>`)
      .join('');

    sections.push(`
      <section>
        <h2 class="s-${status}">${escapeHtml(result.filename)} — ${escapeHtml(headline)}</h2>
        <p class="meta">
          Inspected ${new Date(result.created_at * 1000).toLocaleString()} ·
          sensitivity ${escapeHtml(result.sensitivity)} ·
          alignment ${(result.alignment.quality * 100).toFixed(0)}% ·
          ${result.elapsed_ms.toFixed(0)} ms
        </p>
        <img src="${dataUrl}" alt="Inspected board">
        <table>
          <thead><tr><th>Part</th><th>State</th><th>Confidence</th><th>Reason</th></tr></thead>
          <tbody>${rows}</tbody>
        </table>
      </section>`);
  }

  const html = `<!doctype html>
<html lang="en"><head><meta charset="utf-8">
<title>Inspection report — ${escapeHtml(projectName)}</title>
<style>
  body{font:15px/1.6 -apple-system,"Segoe UI",Roboto,sans-serif;margin:0;padding:40px;
       background:#f6f8fb;color:#101722;max-width:980px;margin-inline:auto}
  h1{font-size:1.7rem;margin:0 0 4px}
  .lead{color:#5b6b80;margin:0 0 32px}
  section{background:#fff;border:1px solid #e2e8f0;border-radius:14px;padding:22px;margin-bottom:22px}
  h2{font-size:1.1rem;margin:0 0 4px}
  .meta{color:#6b7c93;font-size:.82rem;margin:0 0 14px}
  img{width:100%;border-radius:10px;border:1px solid #e2e8f0;display:block;margin-bottom:16px}
  table{width:100%;border-collapse:collapse;font-size:.86rem}
  th{text-align:left;color:#6b7c93;font-weight:600;border-bottom:2px solid #e2e8f0;padding:7px 8px}
  td{padding:7px 8px;border-bottom:1px solid #eef2f7}
  .s-missing{color:#d12c43}.s-review{color:#b26a00}.s-present{color:#0f8f52}
  h2.s-present{color:#0f8f52}h2.s-missing{color:#d12c43}h2.s-review{color:#b26a00}
  footer{color:#8494a8;font-size:.78rem;text-align:center;margin-top:30px}
</style></head>
<body>
  <h1>Inspection report</h1>
  <p class="lead">${escapeHtml(projectName)} · generated ${new Date().toLocaleString()}</p>
  ${sections.join('')}
  <footer>Produced offline by PCB Inspector. Images are embedded in this file.</footer>
</body></html>`;

  downloadBlob(
    new Blob([html], { type: 'text/html' }),
    `inspection-report-${new Date().toISOString().slice(0, 10)}.html`,
  );
}

toolUseResult.content:
/**
 * Inspection results: summary strip, board cards, and the detail inspector.
 *
 * The verdict is shown three times at decreasing distance, because three
 * different people read it: the card banner answers "is this board good?"
 * across the room, the part list answers "which part?", and the expanded row
 * answers "why should I believe you?" with the two crops side by side and the
 * evidence that produced the number. The last one is what earns the operator's
 * trust the first time the tool disagrees with them.
 */

import { CanvasView, drawLabel, roundedRectPath } from './view.js';
import { loadImage, stateColour, formatTime, downloadBlob } from './ui.js';

const STATE_LABEL = { present: 'Present', review: 'Review', missing: 'Missing' };

const ICONS = {
  ok: '<path d="M4 12.5 9.5 18 20 6.5"/>',
  review: '<path d="M12 8v5.5M12 17.2v.1"/><path d="M10.3 3.9 2.6 17.4A2 2 0 0 0 4.3 20.4h15.4a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0Z"/>',
  missing: '<circle cx="12" cy="12" r="8.6"/><path d="M8.8 8.8l6.4 6.4M15.2 8.8l-6.4 6.4"/>',
};

const bannerKind = (status) => (status === 'present' ? 'ok' : status);

/* -------------------------------------------------------------------------
   Overlay rendering
   ------------------------------------------------------------------------- */

/**
 * Draw the board with its verdict boxes at the image's own resolution.
 * Used for card thumbnails and for the exported report.
 */
export function renderOverlayCanvas(image, verdicts, { lineScale = 1 } = {}) {
  const canvas = document.createElement('canvas');
  canvas.width = image.naturalWidth;
  canvas.height = image.naturalHeight;
  const ctx = canvas.getContext('2d');
  ctx.drawImage(image, 0, 0);

  const base = Math.max(canvas.width, canvas.height) / 600;
  const lineWidth = Math.max(1.6, base * 2.1 * lineScale);

  // Present parts first so that a missing box is never hidden under a
  // neighbouring green one.
  const ordered = [...verdicts].sort(
    (a, b) => (a.state === 'present' ? 0 : 1) - (b.state === 'present' ? 0 : 1),
  );

  for (const verdict of ordered) {
    const [x, y, w, h] = verdict.bbox;
    const colour = stateColour(verdict.state);
    ctx.save();
    roundedRectPath(ctx, x, y, w, h, 3 * base);
    if (verdict.state !== 'present') {
      ctx.fillStyle = colour.replace(')', ', 0.22)').replace('rgb', 'rgba');
      ctx.globalAlpha = 0.25;
      ctx.fillStyle = colour;
      ctx.fill();
      ctx.globalAlpha = 1;
    }
    ctx.lineWidth = verdict.state === 'present' ? lineWidth * 0.62 : lineWidth;
    ctx.strokeStyle = colour;
    ctx.stroke();
    ctx.restore();

    if (verdict.state !== 'present') {
      drawLabel(ctx, verdict.name, x, y, colour, {
        fontSize: Math.max(11, base * 11),
        canvasWidth: canvas.width,
      });
    }
  }
  return canvas;
}

/* -------------------------------------------------------------------------
   Batch summary + cards
   ------------------------------------------------------------------------- */

export function renderBatchSummary(host, batch) {
  host.classList.remove('is-hidden');
  host.innerHTML = `
    <div class="stat">
      <span class="stat__value">${batch.count}</span>
      <span class="stat__label">Boards checked</span>
    </div>
    <span class="stat__sep"></span>
    <div class="stat stat--ok">
      <span class="stat__value">${batch.ok_count}</span>
      <span class="stat__label">Complete</span>
    </div>
    <span class="stat__sep"></span>
    <div class="stat stat--missing">
      <span class="stat__value">${batch.missing_boards}</span>
      <span class="stat__label">With missing parts</span>
    </div>
    <span class="stat__sep"></span>
    <div class="stat">
      <span class="stat__value">${batch.total_missing_parts}</span>
      <span class="stat__label">Parts missing in total</span>
    </div>`;
}

export async function renderCards(host, results, onOpen) {
  for (const [index, result] of results.entries()) {
    const card = document.createElement('article');
    card.className = 'board-card';
    card.style.animationDelay = `${Math.min(index * 60, 360)}ms`;
    card.tabIndex = 0;
    card.setAttribute('role', 'button');

    const { status, headline, missing_names: missing, review_names: review } = result.summary;
    const kind = bannerKind(status);

    const chips = [
      ...missing.map((name) => `<span class="chip chip--missing">${escapeHtml(name)}</span>`),
      ...review.map((name) => `<span class="chip chip--review">${escapeHtml(name)}</span>`),
    ];
    if (!chips.length) {
      chips.push(`<span class="chip chip--muted">${result.summary.total_parts} parts verified</span>`);
    }

    card.innerHTML = `
      <div class="board-card__media"><canvas></canvas></div>
      <div class="board-card__banner banner--${kind}">
        <svg viewBox="0 0 24 24" aria-hidden="true">${ICONS[kind]}</svg>
        <span>${escapeHtml(headline)}</span>
      </div>
      <div class="board-card__body">
        <p class="board-card__file" title="${escapeHtml(result.filename)}">${escapeHtml(result.filename)}</p>
        <div class="chips">${chips.join('')}</div>
        <div class="board-card__foot">
          <span>Alignment ${(result.alignment.quality * 100).toFixed(0)}%</span>
          <span>${result.elapsed_ms.toFixed(0)} ms</span>
        </div>
      </div>`;

    card.addEventListener('click', () => onOpen(result));
    card.addEventListener('keydown', (event) => {
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        onOpen(result);
      }
    });

    host.prepend(card);

    // Paint the thumbnail after the card is in the DOM so the layout settles
    // first and the cards appear immediately rather than after every decode.
    loadImage(result.images.test)
      .then((image) => {
        const source = renderOverlayCanvas(image, result.verdicts);
        const target = card.querySelector('canvas');
        const ratio = window.devicePixelRatio || 1;
        const box = target.getBoundingClientRect();
        target.width = Math.round(box.width * ratio);
        target.height = Math.round(box.height * ratio);
        const ctx = target.getContext('2d');
        const scale = Math.min(target.width / source.width, target.height / source.height);
        const w = source.width * scale;
        const h = source.height * scale;
        ctx.drawImage(source, (target.width - w) / 2, (target.height - h) / 2, w, h);
        result._overlay = source;
      })
      .catch(() => { /* thumbnail is cosmetic; the verdict is already shown */ });
  }
}

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (c) => (
    { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]
  ));
}

/* -------------------------------------------------------------------------
   Detail inspector
   ------------------------------------------------------------------------- */

export class DetailView {
  constructor(dialog) {
    this.dialog = dialog;
    this.canvas = dialog.querySelector('#detail-canvas');
    this.host = dialog.querySelector('#viewer');
    this.handle = dialog.querySelector('#compare-handle');
    this.view = new CanvasView(this.canvas, this.host);
    this.view.onChange = () => this.draw();

    this.result = null;
    this.images = null;
    this.mode = 'overlay';
    this.split = 0.5;
    this.hovered = null;

    this._bind();
  }

  _bind() {
    dialogCloseOn(this.dialog, this.dialog.querySelector('#detail-close'));

    this.dialog.querySelector('#detail-view').addEventListener('click', (event) => {
      const button = event.target.closest('button[data-view]');
      if (!button) return;
      this.setMode(button.dataset.view);
    });

    // --- viewer pan / zoom ---
    let panning = null;
    this.canvas.addEventListener('pointerdown', (event) => {
      this.canvas.setPointerCapture(event.pointerId);
      panning = { x: event.clientX, y: event.clientY };
      this.canvas.style.cursor = 'grabbing';
    });
    this.canvas.addEventListener('pointermove', (event) => {
      if (!panning) return;
      this.view.panBy(event.clientX - panning.x, event.clientY - panning.y);
      panning = { x: event.clientX, y: event.clientY };
    });
    const endPan = () => { panning = null; this.canvas.style.cursor = 'grab'; };
    this.canvas.addEventListener('pointerup', endPan);
    this.canvas.addEventListener('pointercancel', endPan);
    this.canvas.style.cursor = 'grab';

    this.canvas.addEventListener('wheel', (event) => {
      event.preventDefault();
      const point = this.view.pointer(event);
      this.view.zoomAt(Math.exp(-event.deltaY * 0.0022), point.x, point.y);
    }, { passive: false });

    // --- compare slider ---
    let dragging = false;
    const move = (event) => {
      if (!dragging) return;
      const rect = this.host.getBoundingClientRect();
      this.split = Math.min(1, Math.max(0, (event.clientX - rect.left) / rect.width));
      this.positionHandle();
      this.draw();
    };
    this.handle.addEventListener('pointerdown', (event) => {
      dragging = true;
      this.handle.setPointerCapture(event.pointerId);
      event.stopPropagation();
    });
    this.handle.addEventListener('pointermove', move);
    this.handle.addEventListener('pointerup', () => { dragging = false; });
  }

  async open(result) {
    this.result = result;
    this.mode = 'overlay';
    this.split = 0.5;
    this.hovered = null;

    this.dialog.querySelector('#detail-title').textContent = result.filename;
    this.dialog.querySelector('#detail-sub').textContent =
      `Inspected ${formatTime(result.created_at)} · ${result.summary.total_parts} parts · `
      + `${result.sensitivity} sensitivity`;

    this._syncModeButtons();
    this.renderSide();

    if (!this.dialog.open) this.dialog.showModal();

    this.images = {
      test: await loadImage(result.images.aligned),
      reference: await loadImage(result.images.reference),
    };

    this.view.resize();
    this.view.setContent(this.images.test.naturalWidth, this.images.test.naturalHeight);
    this.view.fit(16);
    this.positionHandle();
    this.draw();
  }

  setMode(mode) {
    this.mode = mode;
    this._syncModeButtons();
    this.handle.classList.toggle('is-hidden', mode !== 'compare');
    this.positionHandle();
    this.draw();
  }

  _syncModeButtons() {
    for (const button of this.dialog.querySelectorAll('#detail-view button')) {
      button.classList.toggle('is-active', button.dataset.view === this.mode);
    }
    this.handle.classList.toggle('is-hidden', this.mode !== 'compare');
  }

  positionHandle() {
    this.handle.style.left = `${this.split * 100}%`;
  }

  highlight(partId) {
    this.hovered = partId;
    this.draw();
  }

  focusPart(partId) {
    const verdict = this.result?.verdicts.find((v) => v.part_id === partId);
    if (!verdict) return;
    const [x, y, w, h] = verdict.bbox;
    this.view.focusOn(x, y, w, h, 140);
    this.highlight(partId);
  }

  draw() {
    if (!this.images) return;
    const { ctx, scale, tx, ty } = this.view;
    this.view.clear();

    const { test, reference } = this.images;
    const w = test.naturalWidth * scale;
    const h = test.naturalHeight * scale;

    if (this.mode === 'compare') {
      const splitX = this.split * this.view.width;

      ctx.save();
      ctx.beginPath();
      ctx.rect(0, 0, splitX, this.view.height);
      ctx.clip();
      ctx.drawImage(reference, tx, ty, w, h);
      ctx.restore();

      ctx.save();
      ctx.beginPath();
      ctx.rect(splitX, 0, this.view.width - splitX, this.view.height);
      ctx.clip();
      ctx.drawImage(test, tx, ty, w, h);
      ctx.restore();
    } else {
      ctx.imageSmoothingEnabled = scale <= 2;
      ctx.drawImage(test, tx, ty, w, h);
    }

    const ordered = [...this.result.verdicts].sort(
      (a, b) => (a.state === 'present' ? 0 : 1) - (b.state === 'present' ? 0 : 1),
    );

    for (const verdict of ordered) {
      const [bx, by, bw, bh] = verdict.bbox;
      const topLeft = this.view.toScreen(bx, by);
      const rect = { x: topLeft.x, y: topLeft.y, w: bw * scale, h: bh * scale };
      const colour = stateColour(verdict.state);
      const isHovered = this.hovered === verdict.part_id;

      ctx.save();
      roundedRectPath(ctx, rect.x, rect.y, rect.w, rect.h, 3);
      if (verdict.state !== 'present' || isHovered) {
        ctx.globalAlpha = isHovered ? 0.3 : 0.2;
        ctx.fillStyle = colour;
        ctx.fill();
        ctx.globalAlpha = 1;
      }
      ctx.lineWidth = isHovered ? 3 : verdict.state === 'present' ? 1.2 : 2;
      ctx.strokeStyle = colour;
      ctx.stroke();
      ctx.restore();

      if (verdict.state !== 'present' || isHovered) {
        drawLabel(ctx, verdict.name, rect.x, rect.y, colour, { canvasWidth: this.view.width });
      }
    }
  }

  renderSide() {
    const result = this.result;
    const { status, headline } = result.summary;
    const kind = bannerKind(status);

    const verdictBox = this.dialog.querySelector('#detail-verdict');
    verdictBox.className = `verdict verdict--${kind}`;
    verdictBox.innerHTML = `
      <h3>${escapeHtml(headline)}</h3>
      <p>${
        status === 'present'
          ? 'Every named part was found on this board.'
          : status === 'missing'
            ? `Missing: ${result.summary.missing_names.map(escapeHtml).join(', ')}`
            : `Please check: ${result.summary.review_names.map(escapeHtml).join(', ')}`
      }</p>`;

    const alignment = result.alignment;
    const sharpness = result.sharpness || {};
    const warnings = (result.warnings || [])
      .map((text) => `
        <div class="warn-note">
          <svg viewBox="0 0 24 24"><path d="M12 8v5.5M12 17.2v.1"/><path d="M10.3 3.9 2.6 17.4A2 2 0 0 0 4.3 20.4h15.4a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0Z"/></svg>
          <span>${escapeHtml(text)}</span>
        </div>`)
      .join('');

    this.dialog.querySelector('#detail-diagnostics').innerHTML = `
      ${warnings}
      <dl class="diag-row"><dt>Alignment quality</dt><dd>${(alignment.quality * 100).toFixed(0)}%</dd></dl>
      <dl class="diag-row"><dt>Method</dt><dd>${escapeHtml(alignment.method.toUpperCase())}</dd></dl>
      <dl class="diag-row"><dt>Shift corrected</dt><dd>${alignment.translation_px.toFixed(1)} px · ${alignment.rotation_deg.toFixed(2)}°</dd></dl>
      <dl class="diag-row"><dt>Exposure correction</dt><dd>×${(result.photometric.gain ?? 1).toFixed(2)}</dd></dl>
      ${sharpness.sigma ? `<dl class="diag-row"><dt>Focus equalised</dt><dd>σ ${sharpness.sigma.toFixed(2)} px</dd></dl>` : ''}
      ${result.scene_compensation > 0.01 ? `<dl class="diag-row"><dt>Scene compensation</dt><dd>−${result.scene_compensation.toFixed(2)}</dd></dl>` : ''}
      <dl class="diag-row"><dt>Processing time</dt><dd>${result.elapsed_ms.toFixed(0)} ms</dd></dl>`;

    const list = this.dialog.querySelector('#verdict-list');
    list.innerHTML = '';

    const order = { missing: 0, review: 1, present: 2 };
    const sorted = [...result.verdicts].sort(
      (a, b) => order[a.state] - order[b.state] || b.confidence - a.confidence,
    );

    for (const verdict of sorted) {
      list.appendChild(this._verdictRow(verdict));
    }
  }

  _verdictRow(verdict) {
    const item = document.createElement('li');
    item.className = `vrow vrow--${verdict.state}`;

    const thresholds = this.result.thresholds;
    const colour = stateColour(verdict.state);

    const evidence = verdict.evidence
      .map((channel) => `
        <div class="ev-row">
          <span class="ev-row__label">${escapeHtml(channel.label)}</span>
          <span class="ev-row__track">
            <span class="ev-row__fill" style="width:${(channel.score * 100).toFixed(0)}%;background:${colour}"></span>
          </span>
          <span class="ev-row__value">${channel.score.toFixed(2)}</span>
        </div>`)
      .join('');

    item.innerHTML = `
      <button class="vrow__head" type="button">
        <span class="vrow__dot"></span>
        <span class="vrow__name">${escapeHtml(verdict.name)}</span>
        <span class="vrow__state">${STATE_LABEL[verdict.state]}</span>
      </button>
      <div class="vrow__body">
        <p class="vrow__reason">${escapeHtml(verdict.reason)}</p>
        <div class="confidence-bar">
          <div class="confidence-bar__track">
            <span class="confidence-bar__fill" style="width:${(verdict.confidence * 100).toFixed(0)}%;background:${colour}"></span>
            <span class="confidence-bar__mark" style="left:${(thresholds.review * 100).toFixed(0)}%"></span>
            <span class="confidence-bar__mark" style="left:${(thresholds.missing * 100).toFixed(0)}%"></span>
          </div>
          <div class="confidence-bar__legend">
            <span>confidence ${verdict.confidence.toFixed(2)}</span>
            <span>flags at ${thresholds.missing.toFixed(2)}</span>
          </div>
        </div>
        <div class="crops">
          <figure class="crop">
            <img loading="lazy" alt="Reference crop of ${escapeHtml(verdict.name)}"
                 src="/api/runs/${this.result.run_id}/crop/${verdict.part_id}/reference.png">
            <figcaption>Reference</figcaption>
          </figure>
          <figure class="crop">
            <img loading="lazy" alt="This board at ${escapeHtml(verdict.name)}"
                 src="/api/runs/${this.result.run_id}/crop/${verdict.part_id}/test.png">
            <figcaption>This board</figcaption>
          </figure>
        </div>
        <div class="evidence">${evidence}</div>
      </div>`;

    const head = item.querySelector('.vrow__head');
    head.addEventListener('click', () => {
      const open = item.classList.toggle('is-open');
      if (open) this.focusPart(verdict.part_id);
    });
    item.addEventListener('mouseenter', () => this.highlight(verdict.part_id));
    item.addEventListener('mouseleave', () => this.highlight(null));

    // Missing parts start expanded: that is the row the operator opened the
    // dialog to read, and making them click again to see the proof is friction
    // at exactly the wrong moment.
    if (verdict.state === 'missing') item.classList.add('is-open');

    return item;
  }
}

function dialogCloseOn(dialog, button) {
  button.addEventListener('click', () => dialog.close());
  dialog.addEventListener('click', (event) => {
    // Clicking the backdrop (outside the dialog's own box) closes it.
    const rect = dialog.getBoundingClientRect();
    const inside =
      event.clientX >= rect.left && event.clientX <= rect.right &&
      event.clientY >= rect.top && event.clientY <= rect.bottom;
    if (!inside) dialog.close();
  });
}

/* -------------------------------------------------------------------------
   Offline report
   ------------------------------------------------------------------------- */

/**
 * Build a single self-contained HTML file with the images inlined.
 *
 * A report that referenced /api/... would be blank the moment the server
 * stopped, which is precisely when someone wants to read it. Inlining keeps
 * it readable on any machine, forever, with no application at all.
 */
export async function buildReport(results, projectName) {
  const sections = [];

  for (const result of results) {
    const image = result._overlay || renderOverlayCanvas(
      await loadImage(result.images.test), result.verdicts,
    );
    const dataUrl = image.toDataURL('image/jpeg', 0.82);
    const { status, headline } = result.summary;

    const rows = result.verdicts
      .slice()
      .sort((a, b) => b.confidence - a.confidence)
      .map((verdict) => `
        <tr class="s-${verdict.state}">
          <td>${escapeHtml(verdict.name)}</td>
          <td>${STATE_LABEL[verdict.state]}</td>
          <td>${verdict.confidence.toFixed(3)}</td>
          <td>${escapeHtml(verdict.reason)}</td>
        </tr>`)
      .join('');

    sections.push(`
      <section>
        <h2 class="s-${status}">${escapeHtml(result.filename)} — ${escapeHtml(headline)}</h2>
        <p class="meta">
          Inspected ${new Date(result.created_at * 1000).toLocaleString()} ·
          sensitivity ${escapeHtml(result.sensitivity)} ·
          alignment ${(result.alignment.quality * 100).toFixed(0)}% ·
          ${result.elapsed_ms.toFixed(0)} ms
        </p>
        <img src="${dataUrl}" alt="Inspected board">
        <table>
          <thead><tr><th>Part</th><th>State</th><th>Confidence</th><th>Reason</th></tr></thead>
          <tbody>${rows}</tbody>
        </table>
      </section>`);
  }

  const html = `<!doctype html>
<html lang="en"><head><meta charset="utf-8">
<title>Inspection report — ${escapeHtml(projectName)}</title>
<style>
  body{font:15px/1.6 -apple-system,"Segoe UI",Roboto,sans-serif;margin:0;padding:40px;
       background:#f6f8fb;color:#101722;max-width:980px;margin-inline:auto}
  h1{font-size:1.7rem;margin:0 0 4px}
  .lead{color:#5b6b80;margin:0 0 32px}
  section{background:#fff;border:1px solid #e2e8f0;border-radius:14px;padding:22px;margin-bottom:22px}
  h2{font-size:1.1rem;margin:0 0 4px}
  .meta{color:#6b7c93;font-size:.82rem;margin:0 0 14px}
  img{width:100%;border-radius:10px;border:1px solid #e2e8f0;display:block;margin-bottom:16px}
  table{width:100%;border-collapse:collapse;font-size:.86rem}
  th{text-align:left;color:#6b7c93;font-weight:600;border-bottom:2px solid #e2e8f0;padding:7px 8px}
  td{padding:7px 8px;border-bottom:1px solid #eef2f7}
  .s-missing{color:#d12c43}.s-review{color:#b26a00}.s-present{color:#0f8f52}
  h2.s-present{color:#0f8f52}h2.s-missing{color:#d12c43}h2.s-review{color:#b26a00}
  footer{color:#8494a8;font-size:.78rem;text-align:center;margin-top:30px}
</style></head>
<body>
  <h1>Inspection report</h1>
  <p class="lead">${escapeHtml(projectName)} · generated ${new Date().toLocaleString()}</p>
  ${sections.join('')}
  <footer>Produced offline by PCB Inspector. Images are embedded in this file.</footer>
</body></html>`;

  downloadBlob(
    new Blob([html], { type: 'text/html' }),
    `inspection-report-${new Date().toISOString().slice(0, 10)}.html`,
  );
}

input.content:
/**
 * Application shell: wiring, navigation and state.
 *
 * Three screens in a fixed order, because the task itself is ordered -- you
 * cannot name parts without a reference, or inspect without named parts. The
 * stepper disables what is not yet possible rather than letting someone reach
 * a screen that will only tell them off.
 */

import { api, ApiError } from './api.js';
import {
  toast, confirmAction, loadImage, imageFilesFrom, downloadBlob, formatBytes,
} from './ui.js';
import { Annotator } from './annotator.js';
import {
  DetailView, renderBatchSummary, renderCards, buildReport,
} from './results.js';

const $ = (selector) => document.querySelector(selector);

const state = {
  config: null,
  project: null,
  step: 'reference',
  results: [],
  annotator: null,
  detail: null,
  saveTimer: null,
  dirty: false,
};

/* =========================================================================
   Theme
   ========================================================================= */

function initTheme() {
  const stored = localStorage.getItem('pcb-theme');
  const preferred = window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark';
  document.documentElement.dataset.theme = stored || preferred;

  $('#theme-toggle').addEventListener('click', () => {
    const next = document.documentElement.dataset.theme === 'dark' ? 'light' : 'dark';
    document.documentElement.dataset.theme = next;
    localStorage.setItem('pcb-theme', next);
    // Canvas colours are sampled from CSS variables, so both canvases have to
    // be repainted after a theme change.
    state.annotator?.requestDraw();
    state.detail?.draw();
  });
}

/* =========================================================================
   Navigation
   ========================================================================= */

function canEnter(step) {
  if (step === 'parts') return Boolean(state.project?.reference);
  if (step === 'inspect') return Boolean(state.project?.reference) && state.project.parts.length > 0;
  return true;
}

function goTo(step) {
  if (!canEnter(step)) return;
  state.step = step;

  for (const panel of document.querySelectorAll('.panel')) {
    panel.classList.toggle('is-hidden', panel.dataset.step !== step);
  }

  const order = ['reference', 'parts', 'inspect'];
  for (const button of document.querySelectorAll('.stepper__item')) {
    const target = button.dataset.step;
    button.classList.toggle('is-active', target === step);
    button.classList.toggle(
      'is-done',
      order.indexOf(target) < order.indexOf(step) && canEnter(target),
    );
    button.disabled = !canEnter(target);
  }

  if (step === 'parts') {
    // The canvas was display:none until now, so it has no size yet.
    requestAnimationFrame(() => {
      state.annotator?.view.resize();
      state.annotator?.view.fit();
    });
  }
}

/* =========================================================================
   Project
   ========================================================================= */

async function refreshProject(project) {
  state.project = project;

  $('#project-name').textContent = project.name;

  const hasReference = Boolean(project.reference);
  $('#reference-drop').classList.toggle('is-hidden', hasReference);
  $('.card--guide').classList.toggle('is-hidden', hasReference);
  $('#reference-preview').classList.toggle('is-hidden', !hasReference);

  if (hasReference) {
    const url = project.reference_url;
    $('#reference-img').src = url;
    $('#reference-filename').textContent = project.reference.original_filename || 'reference.png';
    $('#reference-size').textContent =
      `${project.reference.width} × ${project.reference.height} px`;
    $('#reference-parts').textContent = String(project.parts.length);

    const image = await loadImage(url);
    if (!state.annotator) createAnnotator();
    state.annotator.setImage(image);
    state.annotator.setParts(project.parts);
    renderPartList();
  }

  $('#sensitivity').value = project.sensitivity;
  goTo(state.step);
}

/* =========================================================================
   Reference upload
   ========================================================================= */

async function uploadReference(file) {
  if (state.project?.reference && state.project.parts.length) {
    const ok = await confirmAction({
      title: 'Replace the reference photo?',
      body: `The ${state.project.parts.length} parts you named belong to the current `
          + 'photo and will be removed, along with the inspection history for this board.',
      confirmLabel: 'Replace',
      danger: true,
    });
    if (!ok) return;
  }

  try {
    toast('Loading reference…', file.name);
    const project = await api.uploadReference(file);
    await refreshProject(project);
    state.results = [];
    $('#results').innerHTML = '';
    $('#batch-summary').classList.add('is-hidden');
    $('#inspect-empty').classList.remove('is-hidden');
    $('#export-report').disabled = true;
    toast('Reference loaded', 'Now draw a box around each part you want checked.', 'success');
    goTo('parts');
  } catch (error) {
    toast('Could not load that photo', error.message, 'error');
  }
}

/* =========================================================================
   Parts editor
   ========================================================================= */

function createAnnotator() {
  state.annotator = new Annotator({
    canvas: $('#annotator'),
    host: $('#canvas-host'),
    emptyHint: $('#canvas-empty'),
    onChange: () => {
      renderPartList();
      scheduleSave();
      updateZoomReadout();
    },
    onSelect: () => renderPartList(),
    onRenameRequest: (id) => {
      const input = document.querySelector(`.part-row[data-id="${id}"] .part-row__name`);
      if (input) {
        input.focus();
        input.select();
        input.scrollIntoView({ block: 'nearest' });
      }
    },
  });
  state.annotator.isActive = () => state.step === 'parts';
  state.annotator.view.onChange = () => {
    state.annotator.requestDraw();
    updateZoomReadout();
  };
}

function updateZoomReadout() {
  if (!state.annotator) return;
  $('#zoom-readout').textContent = `${Math.round(state.annotator.view.scale * 100)}%`;
}

function renderPartList() {
  const annotator = state.annotator;
  if (!annotator) return;

  const parts = annotator.getParts();
  const list = $('#part-list');
  $('#parts-count').textContent = String(parts.length);
  $('#parts-empty').classList.toggle('is-hidden', parts.length > 0);
  $('#reference-parts').textContent = String(parts.length);
  $('#to-inspect').disabled = parts.length === 0;

  const active = document.activeElement;
  const activeId = active?.closest?.('.part-row')?.dataset.id;
  const caret = active instanceof HTMLInputElement ? active.selectionStart : null;

  list.innerHTML = '';
  parts.forEach((part, index) => {
    const row = document.createElement('li');
    row.className = 'part-row';
    row.dataset.id = part.id;
    if (part.id === annotator.selectedId) row.classList.add('is-selected');

    row.innerHTML = `
      <span class="part-row__index">${index + 1}</span>
      <input class="part-row__name" value="" maxlength="40" spellcheck="false"
             aria-label="Part name">
      <span class="part-row__dims">${part.bbox[2]}×${part.bbox[3]}</span>
      <button class="part-row__del" type="button" title="Delete ${part.name}" aria-label="Delete part">
        <svg viewBox="0 0 24 24"><path d="M6 6l12 12M18 6 6 18"/></svg>
      </button>`;

    const input = row.querySelector('.part-row__name');
    input.value = part.name;

    input.addEventListener('focus', () => annotator.select(part.id));
    input.addEventListener('change', () => annotator.renamePart(part.id, input.value.trim()));
    input.addEventListener('keydown', (event) => {
      if (event.key === 'Enter') {
        input.blur();
        event.preventDefault();
      }
      event.stopPropagation();      // let the editor keep Delete / arrows
    });

    row.addEventListener('click', (event) => {
      if (event.target.closest('.part-row__del')) return;
      if (event.target === input) return;
      annotator.focusPart(part.id);
    });

    row.querySelector('.part-row__del').addEventListener('click', (event) => {
      event.stopPropagation();
      annotator.deletePart(part.id);
    });

    list.appendChild(row);
  });

  if (activeId) {
    const restored = list.querySelector(`.part-row[data-id="${activeId}"] .part-row__name`);
    if (restored) {
      restored.focus();
      if (caret !== null) restored.setSelectionRange(caret, caret);
    }
  }
}

function scheduleSave() {
  state.dirty = true;
  clearTimeout(state.saveTimer);
  // Autosave rather than relying on a Save button: losing forty named parts
  // because someone closed a tab is not a recoverable mistake for them.
  state.saveTimer = setTimeout(savePartsNow, 700);
}

async function savePartsNow() {
  if (!state.dirty || !state.annotator) return;
  const parts = state.annotator.getParts().map((part, index) => ({
    id: part.id,
    name: part.name.trim() || `Part ${index + 1}`,
    bbox: part.bbox,
  }));
  try {
    state.project = await api.saveParts(parts);
    state.dirty = false;
    goTo(state.step);
  } catch (error) {
    toast('Could not save the parts', error.message, 'error');
  }
}

async function suggestParts() {
  const button = $('#suggest-parts');
  button.disabled = true;
  button.textContent = 'Detecting…';
  try {
    const { suggestions } = await api.suggest();
    if (!suggestions.length) {
      toast('Nothing detected', 'Draw the boxes by hand — it only takes a moment.', 'warn');
      return;
    }
    state.annotator.addParts(suggestions.map((s) => s.bbox));
    toast(
      `${suggestions.length} candidate parts added`,
      'Rename the ones you care about and delete the rest.',
      'success',
    );
  } catch (error) {
    toast('Auto-detect failed', error.message, 'error');
  } finally {
    button.disabled = false;
    button.innerHTML =
      '<svg viewBox="0 0 24 24" class="btn__icon" aria-hidden="true">'
      + '<path d="m12 3 2.1 5.2L19.5 10l-5.4 1.8L12 17l-2.1-5.2L4.5 10l5.4-1.8Z"/>'
      + '<path d="M18.5 15.5 19.4 18l2.5.9-2.5.9-.9 2.5-.9-2.5-2.5-.9 2.5-.9Z"/></svg>Auto-detect';
  }
}

/* =========================================================================
   Inspection
   ========================================================================= */

async function inspect(files) {
  if (!files.length) return;

  const limit = state.config.max_test_images;
  if (files.length > limit) {
    toast('Too many photos', `Only the first ${limit} will be inspected.`, 'warn');
    files = files.slice(0, limit);
  }

  await savePartsNow();

  const progress = $('#inspect-progress');
  const fill = $('#progress-fill');
  const label = $('#progress-label');

  progress.classList.remove('is-hidden');
  $('#inspect-empty').classList.add('is-hidden');
  label.textContent = files.length === 1
    ? 'Aligning and inspecting 1 board…'
    : `Aligning and inspecting ${files.length} boards…`;

  // The server returns the whole batch at once, so this is an indicator of
  // activity rather than true progress. It is paced to the measured ~0.7 s per
  // board so it does not sit at 90% for ten seconds, and it never reaches
  // 100% until the response actually lands.
  let elapsed = 0;
  const expected = files.length * 850;
  const ticker = setInterval(() => {
    elapsed += 100;
    fill.style.width = `${Math.min(92, (elapsed / expected) * 100)}%`;
  }, 100);

  try {
    const response = await api.inspect(files, $('#sensitivity').value);
    fill.style.width = '100%';

    state.results.push(...response.results);
    renderBatchSummary($('#batch-summary'), cumulativeBatch());
    await renderCards($('#results'), response.results, openDetail);
    $('#export-report').disabled = state.results.length === 0;

    const bad = response.batch.missing_boards;
    if (bad === 0) {
      toast('All boards complete', `${response.batch.count} checked, nothing missing.`, 'success');
    } else {
      toast(
        `${bad} board${bad === 1 ? '' : 's'} with missing parts`,
        `${response.batch.total_missing_parts} part(s) not found. Open a board for detail.`,
        'error',
      );
    }
  } catch (error) {
    toast('Inspection failed', error.message, 'error');
    if (!state.results.length) $('#inspect-empty').classList.remove('is-hidden');
  } finally {
    clearInterval(ticker);
    setTimeout(() => {
      progress.classList.add('is-hidden');
      fill.style.width = '0%';
    }, 420);
  }
}

function cumulativeBatch() {
  return {
    count: state.results.length,
    ok_count: state.results.filter((r) => r.summary.status === 'present').length,
    missing_boards: state.results.filter((r) => r.summary.missing_count > 0).length,
    total_missing_parts: state.results.reduce((sum, r) => sum + r.summary.missing_count, 0),
  };
}

function openDetail(result) {
  if (!state.detail) state.detail = new DetailView($('#detail'));
  state.detail.open(result).catch((error) => {
    toast('Could not open that board', error.message, 'error');
  });
}

/* =========================================================================
   Drag, drop and paste
   ========================================================================= */

function wireDropzone(element, input, handler, { multiple = false } = {}) {
  element.addEventListener('click', () => input.click());
  element.addEventListener('keydown', (event) => {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      input.click();
    }
  });

  input.addEventListener('change', () => {
    const files = imageFilesFrom(input.files);
    if (files.length) handler(multiple ? files : files[0]);
    input.value = '';
  });

  // dragenter/dragleave fire for child elements too; a depth counter keeps the
  // highlight from flickering as the pointer crosses the icon.
  let depth = 0;
  element.addEventListener('dragenter', (event) => {
    event.preventDefault();
    depth += 1;
    element.classList.add('is-over');
  });
  element.addEventListener('dragover', (event) => event.preventDefault());
  element.addEventListener('dragleave', () => {
    depth = Math.max(0, depth - 1);
    if (!depth) element.classList.remove('is-over');
  });
  element.addEventListener('drop', (event) => {
    event.preventDefault();
    depth = 0;
    element.classList.remove('is-over');
    const files = imageFilesFrom(event.dataTransfer.files);
    if (files.length) handler(multiple ? files : files[0]);
  });
}

function wirePaste() {
  window.addEventListener('paste', (event) => {
    const files = Array.from(event.clipboardData?.files || [])
      .filter((file) => file.type.startsWith('image/'));
    if (!files.length) return;
    event.preventDefault();
    if (state.step === 'inspect' && canEnter('inspect')) inspect(files);
    else uploadReference(files[0]);
  });
}

/* =========================================================================
   Menu
   ========================================================================= */

function wireMenu() {
  const menu = $('.menu');
  const button = $('#menu-btn');

  button.addEventListener('click', (event) => {
    event.stopPropagation();
    const open = menu.classList.toggle('is-open');
    button.setAttribute('aria-expanded', String(open));
  });
  document.addEventListener('click', () => {
    menu.classList.remove('is-open');
    button.setAttribute('aria-expanded', 'false');
  });

  $('#menu-panel').addEventListener('click', async (event) => {
    const action = event.target.closest('button')?.dataset.action;
    if (!action) return;
    menu.classList.remove('is-open');

    if (action === 'new') {
      const ok = await confirmAction({
        title: 'Start a new board?',
        body: 'The current board stays saved on disk; this creates a fresh one.',
        confirmLabel: 'Create',
      });
      if (!ok) return;
      state.results = [];
      $('#results').innerHTML = '';
      $('#batch-summary').classList.add('is-hidden');
      $('#inspect-empty').classList.remove('is-hidden');
      await refreshProject(await api.createProject());
      goTo('reference');
      toast('New board created', '', 'success');
    }

    if (action === 'export') {
      try {
        const payload = await api.exportProject();
        downloadBlob(
          new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' }),
          `${state.project.name.replace(/[^\w\- ]+/g, '') || 'board'}.pcbproj.json`,
        );
        toast('Setup exported', 'Reference photo and part names are inside the file.', 'success');
      } catch (error) {
        toast('Export failed', error.message, 'error');
      }
    }

    if (action === 'import') $('#file-import').click();

    if (action === 'clear-runs') {
      await api.clearRuns();
      state.results = [];
      $('#results').innerHTML = '';
      $('#batch-summary').classList.add('is-hidden');
      $('#inspect-empty').classList.remove('is-hidden');
      $('#export-report').disabled = true;
      toast('History cleared', '', 'success');
    }

    if (action === 'about') $('#about').showModal();
  });

  $('#about').querySelector('[data-close]').addEventListener('click', () => $('#about').close());

  $('#file-import').addEventListener('change', async () => {
    const file = $('#file-import').files[0];
    $('#file-import').value = '';
    if (!file) return;
    try {
      const project = await api.importProject(file);
      state.results = [];
      $('#results').innerHTML = '';
      await refreshProject(project);
      toast('Setup imported', `${project.parts.length} parts restored.`, 'success');
      goTo(project.parts.length ? 'inspect' : 'parts');
    } catch (error) {
      toast('Import failed', error.message, 'error');
    }
  });
}

/* =========================================================================
   Boot
   ========================================================================= */

async function main() {
  initTheme();
  wireMenu();
  wirePaste();

  try {
    state.config = await api.config();
  } catch (error) {
    toast('Cannot reach the local server', error.message, 'error');
    return;
  }

  const select = $('#sensitivity');
  select.innerHTML = state.config.sensitivity_presets
    .map((preset) => `<option value="${preset.key}" title="${preset.description}">${preset.label}</option>`)
    .join('');
  select.addEventListener('change', async () => {
    try {
      state.project = await api.patchProject({ sensitivity: select.value });
      const preset = state.config.sensitivity_presets.find((p) => p.key === select.value);
      toast(`Sensitivity: ${preset.label}`, preset.description);
    } catch (error) {
      toast('Could not change sensitivity', error.message, 'error');
    }
  });

  $('#test-drop-hint').innerHTML =
    `or <u>browse</u> &middot; up to ${state.config.max_test_images} at once`;

  wireDropzone($('#reference-drop'), $('#file-reference'), uploadReference);
  wireDropzone($('#test-drop'), $('#file-tests'), inspect, { multiple: true });

  $('#stepper').addEventListener('click', (event) => {
    const button = event.target.closest('.stepper__item');
    if (button) goTo(button.dataset.step);
  });

  $('#to-parts').addEventListener('click', () => goTo('parts'));
  $('#replace-reference').addEventListener('click', () => $('#file-reference').click());
  $('#back-to-parts').addEventListener('click', () => goTo('parts'));
  $('#to-inspect').addEventListener('click', async () => {
    await savePartsNow();
    goTo('inspect');
  });

  $('#zoom-in').addEventListener('click', () => state.annotator?.view.zoomBy(1.25));
  $('#zoom-out').addEventListener('click', () => state.annotator?.view.zoomBy(0.8));
  $('#zoom-fit').addEventListener('click', () => state.annotator?.view.fit());

  $('#suggest-parts').addEventListener('click', suggestParts);
  $('#rename-all').addEventListener('click', () => state.annotator?.autoName());

  $('#clear-parts').addEventListener('click', async () => {
    if (!state.annotator?.count) return;
    const ok = await confirmAction({
      title: 'Remove every part?',
      body: `All ${state.annotator.count} named parts will be deleted. Ctrl+Z undoes this.`,
      confirmLabel: 'Remove all',
      danger: true,
    });
    if (ok) state.annotator.clearParts();
  });

  $('#export-report').addEventListener('click', async () => {
    const button = $('#export-report');
    button.disabled = true;
    try {
      await buildReport(state.results, state.project.name);
      toast('Report saved', 'A self-contained HTML file with the images inside.', 'success');
    } catch (error) {
      toast('Could not build the report', error.message, 'error');
    } finally {
      button.disabled = false;
    }
  });

  $('#project-name').addEventListener('click', async () => {
    const name = prompt('Name this board', state.project.name);
    if (name === null) return;
    state.project = await api.patchProject({ name: name.trim() || state.project.name });
    $('#project-name').textContent = state.project.name;
  });

  // Save pending part edits if the tab is closed or hidden mid-session.
  window.addEventListener('beforeunload', () => {
    if (state.dirty) navigator.sendBeacon?.('/api/health');
  });
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'hidden') savePartsNow();
  });

  try {
    await refreshProject(await api.getProject());
    if (state.project.reference && state.project.parts.length) goTo('inspect');
    else if (state.project.reference) goTo('parts');
  } catch (error) {
    if (error instanceof ApiError) toast('Could not load the project', error.message, 'error');
  }
}

main();

