const c = document.querySelector('#annotator');
const r = c.getBoundingClientRect();
// Pick an empty spot: board top-right quadrant, away from existing boxes.
const p = (x, y) => ({ clientX: r.left + x, clientY: r.top + y, pointerId: 1, button: 0, bubbles: true, isPrimary: true });
const fire = (type, x, y) => c.dispatchEvent(new PointerEvent(type, p(x, y)));
c.setPointerCapture = () => {};
const before = document.querySelector('#parts-count').textContent;
fire('pointerdown', 560, 90);
fire('pointermove', 600, 130);
fire('pointerup',   600, 130);
await new Promise(r2 => setTimeout(r2, 300));
const rows = [...document.querySelectorAll('.part-row')];
({
  before,
  after: document.querySelector('#parts-count').textContent,
  newest: rows.slice(-1).map(x => ({ name: x.querySelector('input').value, dims: x.querySelector('.part-row__dims').textContent })),
  canvasRect: { w: Math.round(r.width), h: Math.round(r.height) },
})

